window.POLICE_LESSONS = {
  "113-hg-1": ["澳門—長崎是葡萄牙在東亞的重要航線","讀題先圈兩個港口。葡萄牙以澳門為據點，把中國絲貨等運往日本，再帶回白銀。","荷蘭後來在長崎也有貿易據點，但題目問的是早期主導澳門到長崎這條路線的國家，選 17 世紀初的葡萄牙。"],
  "113-hg-2": ["開業限制直接影響漢醫能否接續","日治總督府建立以西醫為主的醫療制度，限制漢醫可取得執業資格的途徑，後繼人員因此減少。","甲午戰後割臺是政權轉變的背景；直接使傳統漢醫沒落的是執業制度，故選 D。"],
  "113-hg-3": ["把江南糧運到首都叫漕運","京杭大運河連接南北，可把江南大量糧食運往北京等地，也是官民通行的路線。","絲路以跨區貿易為主。永濟渠是較早的運河段與水路系統，題目描述的是連接江南和京師的整體路線。"],
  "113-hg-4": ["琉球船民遇害與日本併吞琉球的時序","1871 年琉球船民漂到臺灣後遇害。日本在 1872 年將琉球改為琉球藩，1874 年又以遇害事件為由出兵臺灣。","1879 年廢藩置沖繩縣。題目把 1871–1874 年的相關事件合稱牡丹社事件，所以選 C。注意改藩早於 1874 年出兵。"],
  "113-hg-5": ["戰時動員與奉仕是日治後期的線索","女學生為士兵送行、做物資與服務工作，顯示戰爭時期把學校及學生編入動員。","皇民化運動屬日治後期。內地延長主義是較早的施政方向，不能只看到日式教育就選它。"],
  "113-hg-6": ["由神明的稱謂理解民間形象","『夫人、天妃、天后』借用傳統女性尊稱，民間『媽祖婆』又以親近的女性長輩稱呼神明。","考題選 A，重點是女神慈愛、庇護的形象。冊封屬敬稱，並不表示神明具有皇室血緣。"],
  "113-hg-7": ["用最早的移民背景辨認國家","題目從英格蘭殖民者起頭，後面又列愛爾蘭、義大利、德國等歐洲移民，和美國移民歷史相符。","墨西哥早期深受西班牙殖民，巴西深受葡萄牙殖民，海地的殖民史則與法國密切相關。"],
  "113-hg-8": ["東北的清政權與東南的鄭氏","來自中國東北的是滿洲建立的清政權；東南海商家族指鄭氏。1683 年清軍擊敗鄭氏，隔年設臺灣府。","1683、1684 年都落在 1601–1700 年，也就是 17 世紀。"],
  "113-hg-9": ["朝鮮在 19 世紀末廢除科舉","題目描述受鄰國壓力而改革，符合朝鮮 1894 年甲午改革，當時日本勢力介入，科舉亦被廢除。","中國正式廢科舉是在 1905 年，已是 20 世紀初。"],
  "113-hg-10": ["宋明理學強調綱常、忠貞與節義","題目說虞姬的形象由感情上的殉情，轉為對丈夫守貞、對君王盡忠的殉節。","這些倫理要求與宋明理學影響下的綱常觀念最吻合。"],
  "113-hg-11": ["文藝復興重新重視希臘、羅馬典籍","拉丁文是讀古羅馬詩人魏吉爾作品的工具。文法學校教授古典語文，反映人文主義下的古典教育。","吳爾芙是 20 世紀作家，題目問她筆下的英格蘭時代，不能拿作者年代答題。"],
  "113-hg-12": ["戰後改推國語，造成書寫語言轉換","作家先在日治臺灣接受日文教育，政權移交後，新政府推廣以華語為主的國語政策，使他需要改變使用的語言。","1930、40 年代的皇民化反而加強日語。題目問的是戰後 1940、50 年代。"],
  "113-hg-13": ["越南的殖民經驗與羅馬字","越南的國語字以拉丁字母書寫，早期由傳教士發展，法國殖民政府後來推廣使用。","題目問將這種文字宣稱為殖民功績的國家，選法國。1945 年的官方採用與早期文字發展是不同階段。"],
  "113-hg-14": ["大規模引進西方制度是明治維新的特徵","題幹列舉軍事、科學、教育制度一起改造，官員還到海外考察。明治政府希望以這些改革追上西方。","鎖國幕府限制對外往來，與題中的主動引進、出訪和通商很不同。"],
  "113-hg-15": ["冷戰的反共氛圍滲入大眾媒體","『莫斯科』『共產黨員』『進到你客廳』反映美國對蘇聯與共產主義影響的高度警惕。","好萊塢、電視、廣播成為審查或抵制對象，是冷戰期間美蘇對立下的文化現象。"],
  "113-hg-16": ["東亞季風區可先抓共同風向與季節","冬季多從大陸吹向海，夏季多從海洋吹向陸，三地的季風方向相近。三地夏天也都較炎熱。","降水量和全年溫差受海陸距離、地勢等影響差異較大，故選丙、丁。"],
  "113-hg-17": ["大比例尺能看清小範圍細節","大比例尺通常搭配較小的等高距，可呈現細節，甲正確。相同大小紙張，小比例尺涵蓋較廣，丁正確。","燈柱位置與鄉鎮內單一學校的受損調查都需要較詳細的圖，乙和丙不合。"],
  "113-hg-18": ["臺灣降雨多，缺水要看平均分配和可利用量","人口密、下雨集中在部分季節與地區、坡陡流急使水很快入海，都會讓可用水量受限。","題目問『並非』。河流坡降小、年降水量少不符合臺灣整體特徵，所以選丙、戊。"],
  "113-hg-19": ["什葉派主要分布區可先記伊朗","伊朗人口以什葉派穆斯林為主，所以選伊朗高原。","阿拉伯半島與土耳其等許多地區主要為遜尼派。題目問主要分布，並不要求區域只存在一個教派。"],
  "113-hg-20": ["擴散是都市活動延伸到周邊","通勤月票降低跨縣市交通成本，讓居住與通勤範圍由雙北伸展到基隆、桃園。","題幹強調服務及生活圈向外延伸，因此屬擴散。若強調周邊的人才與資源被吸往核心，才接近反吸。"],
  "113-hg-21": ["暖流使北歐部分沿岸冬季較暖","看圖，甲在斯堪地那維亞西側沿岸，己在冰島。兩地接近北大西洋暖流水域。","暖流把較暖的海水及熱量帶往高緯度，在冬季對鄰近海岸有增溫作用，故選洋流。"],
  "113-hg-22": ["迎風、背風會讓鄰近地方雨量差很多","甲在斯堪地那維亞山脈西側。潮濕西風吹上迎風坡，抬升冷卻後多降雨。","乙在較背風的一側，降水較少。這題同時需要地形向背與盛行風向，所以選甲、丁。"],
  "113-hg-23": ["伊比利半島西北部受大西洋調節","面向大西洋，潮濕海風帶來較充足降雨，且海水調節氣溫，使年溫差較小。","西北部較符合溫帶海洋性氣候。半島其他許多地區是地中海型，但不能以全半島一概而論。"],
  "113-hg-24": ["風向以風吹來的地方命名","從印度洋西側往東航向麻六甲，需要由西南吹向東北的風，故甲是西南季風。","冬季風向轉為東北季風，可供回程。『等待風向改變』也是季風會隨季節反轉的線索。"],
  "113-hg-25": ["地中海型氣候夏乾冬雨，坡地多見葡萄與橄欖","藍白建築、鄰近西亞與古文明指向希臘一帶，山地多，夏季少雨，不利某些糧食作物，甲正確。","坡地適種葡萄及橄欖，可加工為酒和油，丙正確。乙寫成夏雨，丁寫地勢平坦，皆與此區不合。"],
  "113-hg-26": ["用兩側水域辨認海峽","紅海南端通往亞丁灣的通道是曼達布海峽，位在葉門與非洲之角之間。","荷莫茲海峽通往波斯灣，直布羅陀海峽接地中海和大西洋。先認海峽所連接的水域，再選答案。"],
  "113-hg-27": ["吳哥窟最初是印度教寺廟","柬埔寨的吳哥窟最初為供奉印度教神祇而建，後來也成為佛教場所。","題目問其主要的建築、起源宗教文化，選印度教。今天柬埔寨的主要信仰不能直接套回建造年代。"],
  "113-hg-28": ["氣候圖的關鍵是高溫月降雨是否反而少","圖上 6–8 月的溫度高，月雨量偏低。11 月、12 月等較冷的月份降雨較多。","夏乾、冬雨是地中海型氣候的辨識重點。"],
  "113-hg-29": ["地形剖面用地名與南北方向定位","圖上由南到北，依序看到地中海、波河、阿爾卑斯山、多瑙河及斯堪地那維亞山脈。","跨過這些地形需要從義大利附近沿中歐北上，大致對應東經 10°。50°N 是東西向緯線。"],
  "113-hg-30": ["風帶隨季節移動，形成莽原的乾濕季","巴西高原夏季受間熱帶輻合區及上升氣流影響，較多對流降雨。","冬季受副熱帶高壓及下沉氣流影響，條件較乾，故依序是間熱帶輻合區、副熱帶高壓帶。"],
  "113-hg-31": ["把直接導火線與殖民治理背景分開","三案的日期都在日治時期，殖民當局的治理與山林開發損及原住民族權益。依官方答案選 B、C、D，D 可理解為樟腦等資源開發的背景。","三案並非都在阿美族居住區，也早於戰時徵調出兵。其中七腳川事件另有勞役、薪資等直接導火線。"],
  "113-hg-32": ["政府主導遷徙要有政策推動","明治政府開發北海道、清廷推動雲貴地區屯墾、日治政府推動原住民族移住，分別對應 A、C、D。","吳沙入蘭墾殖以民間活動為主；雲南回民外遷要從動亂與避難理解。"],
  "113-hg-33": ["看該時該地是否受日本控制","1920 年代朝鮮、1930 年代臺灣、1940 年代滿洲國均在日本支配範圍內，可能用神社傳播天皇信仰。","1860 年代菲律賓仍在西班牙殖民時期，1880 年代印度受英國統治，因此選 C、D、E。"],
  "113-hg-34": ["分辨跨洋勞動遷移與各地農業人口","南美甘蔗與北美棉花園的非洲人遭奴役；東南亞橡膠園有華工，夏威夷甘蔗園有朝鮮移民勞工，對應 A、B、D、E。","C 的阿利安人與題目所指時期的跨區種植園勞動移民不吻合。"],
  "113-hg-35": ["明清集中皇權的三種制度","明太祖廢宰相，清代以密摺讓皇帝直接掌握資訊，軍機處使重要政務可由皇帝集中決策，故選 B、C、E。","三省六部在隋唐發展成熟，編戶齊民遠早於明清，不合題目年代。"],
  "113-hg-36": ["孟加拉的水患由降雨、風暴與地形共同影響","西南季風帶來雨季的大量降雨，孟加拉灣熱帶氣旋也可能帶來暴雨與風暴潮。","低平三角洲排水慢、易淹水，三個因素對應 A、C、D。"],
  "113-hg-37": ["商品圈若小於商閾，客源可能不足","商品圈是可吸引顧客的範圍，商閾表示維持營運需達到的最低市場規模。逐家將商品圈與商閾相比。","B 為 40＜45，D 為 35＜40，E 為 25＜30。A、C 的實際範圍大於門檻。"],
  "113-hg-38": ["三角貿易分三段逐一比對","非洲到美洲運送被奴役者；歐洲到非洲運送軍火等商品；美洲到歐洲則輸出原料、貴金屬等。","所以 A、B、C 正確。紡織品多屬歐洲貨品，棉花、蔗糖是美洲出口的代表。"],
  "113-hg-39": ["把大西洋三角貿易沿順時針環流讀一圈","從非洲西岸向美洲可借北赤道洋流；由美洲往歐洲可沿墨西哥灣流及北大西洋暖流。","再經加那利洋流沿非洲西北岸南下，故選 B、C、D、E。本吉拉洋流在南大西洋。"],
  "113-hg-40": ["人口自然增加率＝出生率減死亡率","圖中甲是死亡率，乙是出生率。第二階段乙仍高，甲先明顯下降，於是人口快速增加，選 A。","第三階段甲已偏低，乙開始快速下降，主導人口成長減緩，選 E。丙是總人口，反映累積結果。"],
  "113-mb-1": ["巢狀根號可試著配成平方","14±8√3＝(2√2±√6)²，因為 8＋6＝14，且 2×2√2×√6＝8√3。","2√2＞√6，所以兩個根號分別化為 2√2＋√6、2√2−√6，相加是 4√2。"],
  "113-mb-2": ["取對數把指數 n 拉到前面","三邊取常用對數，得到 2≤n(log3−log2)≤log500。代入 log3−log2≈0.1761，log500＝3−log2≈2.699。","相除得約 11.36≤n≤15.33，因此 n 為 12、13、14、15，共 4 個。"],
  "113-mb-3": ["三點共線時斜率相同","前兩點的斜率是 (log3−log2)/(3−2)＝log(3/2)。從第一點到第三點，x 增加 4。","因此 log a＝log2＋4log(3/2)，a＝2(3/2)⁴＝81/8。"],
  "113-mb-4": ["同一個夾角連用兩次餘弦定理","在 △ABC 中，cos B＝(7²＋8²−5²)/(2×7×8)＝11/14。D 在 BC 上，所以 ∠ABD 也是角 B。","在 △ABD 中，AD²＝7²＋6²−2×7×6×11/14＝19，所以 AD＝√19。"],
  "113-mb-5": ["對角矩陣的平方只需把對角元素平方","A² 的對角為 a²、b²。若等於單位矩陣，兩個位置都必須等於 1。","a、b 都各可取 1 或 −1，所以有 2×2＝4 個矩陣。"],
  "113-mb-6": ["平行平面共用法向量","本題官方送分。依代數上的帶正負截距解讀，設 E 為 2x＋y−3z＝d；三個截距是 d/2、d、−d/3，相加為 14 得 d＝12。","兩平面的距離是 |15−12|/√(2²＋1²＋(−3)²)＝3/√14。解題練習可用此法，作答仍依公告一律給分。"],
  "113-mb-7": ["完全平方數的每個質因數次方都是偶數","1、4、9 本身為平方數；2 與 8 的奇次質因數同為 2，把它們配其中一個平方數有三組；三個平方數全取另有一組。","剩下能讓奇次質因數成對的是 2、3、6 與 3、6、8。5、7 各找不到配對，總共 6 組。"],
  "113-mb-8": ["用 AB 的兩列等式各自解一欄","第一欄滿足 a＋2c＝2、3a＋4c＝0，解得 a＝−4、c＝3。第二欄滿足 b＋2d＝0、3b＋4d＝2，解得 b＝2、d＝−1。","四數相加 −4＋3＋2−1＝0。"],
  "113-mb-9": ["係數的範圍會等比例放大平行四邊形","AB、AC 張成的平行四邊形面積是 △ABC 的兩倍，即 8。r 的區間長 3，s 的區間長 2。","P 的區域由兩方向分別放大 3 與 2，面積 8×3×2＝48。"],
  "113-mb-10": ["總和為偶數時，奇數個數必為偶數","1 至 15 有 7 個偶數、8 個奇數。全選偶數有 C(7,3)＝35 種。","選兩個奇數和一個偶數有 C(8,2)×7＝196 種，共 231。"],
  "113-mb-11": ["恆正表示整條拋物線都在 x 軸上方","a＝−1 開口向下；a＝0 時代 x＝0 得 −1；a＝1 時式子為 (x＋1)²，在 x＝−1 等於零。","a＝2 時，2x²＋3x＋3＝2(x＋3/4)²＋15/8，對所有實數都大於零。"],
  "113-mb-12": ["抽三球不放回且只問顏色組合","總共 9 球取 3 球，有 C(9,3)＝84 種等可能組合。三球異色必須白、紅、黃各一。","合格組合為 2×4×3＝24 種，機率 24/84＝2/7。"],
  "113-mb-13": ["把兩條邊向量分解成沿摺線和垂直摺線","在 B 點，BA、BC 都與 BD 夾 45°。若邊長取 1，兩者沿 BD 的分量長都為 1/√2。","垂直 BD 的兩個分量也各長 1/√2，夾角依題意取 60°。內積為 1/2＋(1/2)cos60°＝3/4，即 cosθ。"],
  "113-mb-14": ["驗出陽性的人包含真陽性與偽陽性","以 1000 人想像，60 人患病，約 60×0.9＝54 人驗出陽性；940 人未患病，約 940×0.05＝47 人也驗出陽性。","在陽性的 101 人中，患病者是 54 人，所以條件機率為 54/101。"],
  "113-mb-15": ["切線垂直於通過切點的半徑","圓心 (−2,1) 到切點 (1,0) 的斜率為 −1/3，切線斜率為 3。過切點得到 y＝3x−3。","x 截距為 1，y 截距為 −3，三角形兩直角邊長 1、3，面積為 3/2。"],
  "113-mb-16": ["把限制式與所求式的分量配成相同順序","本題官方送分。令 w＝2z，則 x²＋y²＋w²＝6，而所求為 (2,−1,1)·(x,y,w)−3。","兩個向量長都為 √6，因此內積最多為 6；取 (x,y,w)＝(2,−1,1) 可達到，最大值 3。"],
  "113-mb-17": ["找分母與分子的和固定的一組","數列按分子＋分母＝2、3、4……分組，每組分子依序從 1 開始。7/13 在總和 20 的組，是該組第 7 項。","前面組別有 1＋2＋…＋18＝171 項，加 7 得第 178 項。"],
  "113-mb-18": ["統一寫成第一象限的正弦才能比大小","cos(π/5)＝sin(3π/10)；sin 2＝sin(π−2)。π/6、3π/10、1、π−2 約為 0.524、0.942、1、1.142。","這些角都在 0 到 π/2，正弦隨角度增大，因此 sin 2 最大。"],
  "113-mb-19": ["用二項式定理辨認展開式","各項是 C(20,k)×3ᵏ，因此總和為 (1＋3)²⁰＝2⁴⁰。","log(2⁴⁰)≈40×0.3010＝12.04，在 12 和 13 之間，所以數落在 10¹² 到 10¹³ 之間，共 13 位。"],
  "113-mb-20": ["根號表示與固定點的空間距離","本題官方送分。根號內為點 (x,y,z) 與 (−5,1,−3) 各坐標的差平方和。最小值是固定點到平面的垂直距離。","將固定點代進 x−2y＋2z−5 得 −18，再除以法向量長 √(1＋4＋4)＝3，距離為 6。"],
  "113-mb-21": ["等差數列對稱的兩項平均是中間項","a₂＋a₁₀＝2a₆，b₂＋b₁₀＝2b₆。前 11 項也以第 6 項為中間，所以 S₁₁＝11a₆、T₁₁＝11b₆。","所求比為 S₁₁/T₁₁＝(7×11＋3)/(2×11＋5)＝80/27。"],
  "113-mb-22": ["把兩個向量寫成坐標後展開內積","取 P=(x,y)，PA·PB＝x²＋y²−4√3x−4y＝4−(4√3,4)·(x,y)。","固定向量長 8，OP 長 2。兩者反向可讓內積最小為 −16，故所求最大為 4＋16＝20。"],
  "113-mb-23": ["兩種倍增速度相除，就得到每小時的比值","初始數量相同，過 t 小時後比值 B/A＝4ᵗ/2ᵗ＝2ᵗ。","512＝2⁹，因此 t＝9 小時。"],
  "113-mb-24": ["比較函數值找最大值","本題官方送分。依題給函數，f(2)＝64，且 64−f(t)＝(t−2)²(t＋4)。","t≥0 時右側非負，並且只有 t＝2 時等於零，因此依式計算是第 2 日達最大。"],
  "113-mb-25": ["圓柱的平面截面由切割方向決定","水平切可得圓，通過中軸的直切可得長方形，適當斜切可得橢圓。通過圓柱中心時，兩半可等體積。","平面切單一圓柱側面沒有雙曲線的兩支形狀，因此選 C。"],
  "113-mb-26": ["將三條彼此垂直的稜當作三個坐標軸","以 D 為原點取 A=(2,0,0)、B=(0,4,0)、C=(0,0,4)。AD 與 BD 垂直，CD 又垂直底面。","P=(1,0,0)，Q=(0,2,2)。PQ＝√(1²＋2²＋2²)＝3。"],
  "113-mb-27": ["三人中恰有二人命中，分誰沒中","丙沒中是 0.6×0.7×0.5＝0.21；乙沒中是 0.6×0.3×0.5＝0.09。","甲沒中是 0.4×0.7×0.5＝0.14，三種互斥結果相加為 0.44。"],
  "113-mb-28": ["立方差可用 x²＋y² 和 xy","依題 x²＋y²＝12，xy＝√(36−20)＝4。x＞y，所以 x−y＝√(12−8)＝2。","x³−y³＝(x−y)(x²＋xy＋y²)＝2(12＋4)＝32。"],
  "113-mb-29": ["用象限決定三角函數的符號","tan 140°＝−tan 40°，sin 230°＝−sin 50°＝−cos 40°。","因 40° 在第一象限，cos 40°＝1/√(1＋tan²40°)＝1/√(1＋k²)，再補上負號。"],
  "113-mb-30": ["緯圈半徑＝地球半徑×cos 緯度","北緯 30° 的緯圈半徑為 6370×cos30°＝3185√3 公里。","題目問直徑，要再乘 2，得到 6370√3 公里。"],
  "113-mb-31": ["兩條半徑方向相差 90°","極坐標給 OA＝2、OB＝4，角度相差 220°−130°＝90°，所以 △AOB 以 O 為直角。","AB＝√(2²＋4²)＝2√5。直角三角形斜邊中點距三頂點等遠，OC＝AB/2＝√5。"],
  "113-mb-32": ["用對稱中心找配對零點和正負","中心 (2,0) 是零點，f(0)＝0 的對稱零點在 x＝4。因此 f(x)＝a·x(x−2)(x−4)。f(−3)＞0 迫使 a＜0。","逐一看三因式的符號，f(−2)、f(3) 為正，f(4)＝0，其餘為負，所以只有 2 個。"],
  "113-mb-33": ["把圓心平移到原點再逐欄數格點","令 u＝x−3、v＝y＋4，條件變成 u²＋v²≤5 與 u＋v≤1。u 只可能為 −2、−1、0、1、2。","五欄可取的 v 分別為 −1～1、−2～2、−2～1、−2～0、−1。格點數 3＋5＋4＋3＋1＝16。"],
  "113-mb-34": ["河邊那一側不用繩，只有三邊計入","設垂直河岸的一邊長 x，另一種邊長 20−2x，面積 S＝x(20−2x)。","配成 S＝50−2(x−5)²，x＝5 時取得最大面積 50。"],
  "113-mb-35": ["兩歪斜線的距離沿共同垂線量","本題官方送分。設正立方體邊長 s。正四面體的邊是立方體面對角線，所以 s√2＝2，s＝√2。","依坐標圖，AB、CD 的中點分別是 (s/2,0,s/2)、(s/2,s,s/2)，連線沿 y 軸，垂直兩邊。所求為 s＝√2，原選項無此值。"],
  "113-mb-36": ["迴歸直線通過兩科平均組成的點","斜率為 rσᵧ/σₓ＝0.8×5/10＝0.4。國文從平均 65 增至 70，多 5 分。","預測英文從平均 70 增加 0.4×5＝2，得到 72 分。"],
  "113-mb-37": ["把已知兩個向量相加或相減來找矩陣的兩欄","兩式相加得 A(2,0)=(0,2)，第二式減第一式得 A(0,2)=(−2,0)。因此 A(e₁)=(0,1)，A(e₂)=(−1,0)。","A 使向量逆時針轉 90°，A³ 等於逆時針轉 270°，矩陣第一列 (0,1)、第二列 (−1,0)。"],
  "113-mb-38": ["把長方體的相鄰表面展開，再在平面走直線","從對角頂點 A 到 G，有三種本質不同的長方形寬長，分別是 (4＋3,2)、(4＋2,3)、(3＋2,4)。","對角線長為 √53、√45、√41，最短是 √41。"],
  "113-mb-39": ["正三角形的外接圓半徑可求邊長","A 在圓上且 OA＝√(3²＋4²)＝5，所以外接圓半徑為 5。正弦定理給邊長＝2×5×sin60°＝5√3。","面積＝(√3/4)(5√3)²＝75√3/4。"],
  "113-mb-40": ["相關係數比較偏差是否同向變動","逐欄算國文偏差 x−64、英文偏差 y−70。偏差乘積相加是 216，兩組偏差平方和分別是 144、576。","r＝216/√(144×576)＝216/(12×24)＝0.75。"],
  "113-en-1": ["aspect＝方面、面向","句子說，在全球化的世界，有效溝通需要了解一個社會的文化面向。cultural aspect 是常見搭配。","adoption 是採用或收養，landmark 是地標，sample 是樣本。"],
  "113-en-2": ["reflect＝反映","建築細節讓人看出古文明的文化傳承和價值觀，所以用 reflect。","afford 是負擔得起，insert 是插入，shelter 是庇護。"],
  "113-en-3": ["financial difficulties＝財務困難","醫療支出突然增加或失業，直接影響家裡的金錢收支，因此選 financial。","flexible 是有彈性的，distinct 是不同的，doubtful 是可疑或不確定的。"],
  "113-en-4": ["social status＝社會地位","職業、教育、家庭背景都可能影響人在社會中的地位。把 social 和 status 一起記。","quantity 是數量，prosperity 是繁榮，evidence 是證據。"],
  "113-en-5": ["distinguish between A and B＝分辨 A 與 B","A 是可靠資訊，B 是假新聞。看到 between… and…，可先想是否在比較兩者。","violate 是違反，rescue 是救援，project 可指投射或預測。"],
  "113-en-6": ["proper＝適當的","運動表現和健康需要合適的飲食。maintain a proper diet 是維持適當飲食。","apparent 是明顯的，literary 是文學的，immediate 是立即的。"],
  "113-en-7": ["excessive＝過度的","都市人口持續增加，住房和公共建設面臨過大的需求。excessive demands 指需求超出一般可負荷的程度。","innovative 是創新的，relative 是相對的，liberal 可指自由開放的。"],
  "113-en-8": ["symbol of＝……的象徵","畫作用看得見的畫面呈現藝術家內心看不見的掙扎，因此是 a symbol of his or her struggle。","sacrifice 是犧牲，column 是柱或專欄，agriculture 是農業。"],
  "113-en-9": ["religious＝宗教的","believers 是信徒，blessings 是祝福或庇佑，兩個線索指向宗教儀式。","efficient 是有效率的，brutal 是殘酷的，innocent 是無辜的。"],
  "113-en-10": ["suffer from＝受……所苦","後文說爸爸必須用止痛藥，因此他受嚴重背痛所苦。單數主詞 my dad 用 suffers。","attend to 是照料或處理，put out 可指撲滅，take over 是接管。"],
  "113-en-11": ["along with＝和……一起","老師與校長都認為學生應被停學。逗號中的 along with the school principal 補充另一個人。","above all 是最重要的是，on the whole 是整體而言，on average 是平均來說。"],
  "113-en-12": ["be faced with＝面臨","Gary 同時錄取兩所名校，得選其中一所，因而面臨難作的決定。a dilemma 是兩難。","envious of 是羨慕，suspicious of 是懷疑，charged with 可指被控告。"],
  "113-en-13": ["pose a threat to＝對……構成威脅","句子描述碳排放大量增加對環境的影響，後文又提到氣候變遷，因此搭配 poses a threat to。","pay attention to 是留意，catch a glimpse of 是瞥見，take a stand 是表明立場。"],
  "113-en-14": ["be addicted to＝對……上癮","每天花好幾小時滑社群媒體，描寫的是難以停止的使用習慣。addicted to 後可接 smartphones 或使用手機的動作。","associated with 僅表示有關，destined for 是注定前往，startled by 是被……嚇到。"],
  "113-en-15": ["be composed of＝由……組成","氮、氧及二氧化碳是大氣的組成成分，因此用 is composed of。","consist of 也有同義，但直接寫 The atmosphere consists of…，不能加 is 成為 is consisted of。"],
  "113-en-16": ["even if＝即使","空格後 you keep asking 是完整子句。句意是即使你整天要求，我仍不讓你獨自夜間外出。","in spite of 後接名詞片語；since 表原因；only if 表必要條件。"],
  "113-en-17": ["require that ＋ 主詞 ＋ 原形動詞","require 在這裡表示要求，因此 that 子句用原形。作業是『被』繳交，所以用 be submitted。","只寫 submitted 會缺少被動助動詞；submit 則變成作業主動繳交。"],
  "113-en-18": ["English-speaking＝說英語的","空格要用一個形容詞修飾 country。用 English-speaking country 表示以英語溝通的國家。","spoken English 指的是英語口語，本身是名詞片語。"],
  "113-en-19": ["whichever＋名詞＝任何一個你選的……","題目允許從圖書館選一本偏好的書，所以 whichever book you prefer 可當 choose 的受詞。","whether 是是否，wherever 是無論何處，no matter 須再接疑問詞。"],
  "113-en-20": ["with＋受詞＋形容詞表示當時的狀態","門在離開時一直是開著的，後句小偷容易進入正好印證。the door open 裡的 open 是形容詞。","opening 或 being opened 著重正在打開的動作，與遺留的狀態不同。"],
  "113-en-21": ["Having＋過去分詞表示先完成的經歷","兩人先一起經歷起伏，現在才成為理想伴侶。因此用 Having experienced，時間順序是過去經驗在前。","experienced 在這裡需要主動、能帶受詞 many ups and downs。"],
  "113-en-22": ["were to＋原形可假設未來很難發生的情況","山海消失後才答應結婚，是說話者明知幾乎不會發生的假設。if 子句用 were to disappear。","主句 would marry 與此假設搭配。had disappeared 通常是假設過去已發生的事。"],
  "113-en-23": ["is estimated to be＋過去分詞","七成的地表被水覆蓋，語意是被動：is covered by water。估計句型用 is estimated to…，合起來成 to be covered。","另一種寫法是 It is estimated that…，若保留地表當主詞，就用題目的不定詞寫法。"],
  "113-en-24": ["Only when 放句首，主要子句會倒裝","太陽落下以後夜行動物才出現。Only when the sun sets 放句首，後面才有 do the animals emerge 的倒裝。","when 子句仍保持 the sun sets 的順序。If only 比較常用來表達但願。"],
  "113-en-25": ["疑問詞＋to＋原形＝簡化的間接問句","Jessie 想知道假期要去哪，所以是 wondered where to go。around the corner 表示節日快到了。","when to do 缺受詞；題目也沒提供可供選擇的遊戲讓 which to play 取得意義。"],
  "113-en-26": ["主旨需涵蓋音樂與戰時情緒兩條線","文章先說音樂普及，接著說政府用它激發愛國心、爭取支持，最後擴展到政治運動。","B 涵蓋主要內容。文章沒有說音樂曲風的變化引起社會革命。"],
  "113-en-27": ["細節題回到政府使用音樂的段落","第二段直接列出 pride、patriotism，政府用音樂鼓動民眾，詞譜圖像也增加宣傳效果。","D 正好對應這兩個字；作曲家其實有合作寫歌，與 B 相反。"],
  "113-en-28": ["把好幾種情緒反應合成合理推論","文中說戰時音樂能讓人興奮、願意幫忙，也可能讓不支持戰爭的人感到內疚。","由此可推知音樂能影響甚至操弄情緒。作者描述效果，沒有判斷它不道德。"],
  "113-en-29": ["saturate 的核心是浸透、遍及","後面說 reached into all of its corners，換成白話就是流行音樂深入社會每個角落。","四個選項中 A influence 最接近『廣泛影響』，實際字義比單純的 influence 更強。"],
  "113-en-30": ["用文章明示主題回答","一戰時，美國用音樂鼓舞民眾並爭取支持，第二段直接用 patriotism 表示愛國情感。","題目問符合文章敘述的歌詞主題，所以選 Patriotism。"],
  "113-en-31": ["give rise to 與 result in 都表示導致","酒駕是原因，致命交通事故是結果。C、E 都能接結果。","arise from 的方向相反，主詞是結果，from 後面放原因。"],
  "113-en-32": ["conduct a project / carry out a project＝執行計畫","spend time doing something 表花時間做某事。conducting 和 carrying out 都能接科學計畫。","surrender to 是向……投降，impose on 是強加於，語意不合。"],
  "113-en-33": ["紀念或致敬的三種片語","in memory of、in honor of、in remembrance of 都可表示為了紀念或致敬。題句描述泰姬瑪哈陵的建造用意。","in need of 表需要；in search of 表尋找。"],
  "113-en-34": ["be worth V-ing / be worthy of being V-ed","worth watching 是值得看；worthy of being watched 也可表示值得被觀看。兩個句型對應 B、D。","worthless 是沒有價值；單獨 worth 缺後面內容。"],
  "113-en-35": ["遵守法律的三種表達","comply with the law、abide by the law、obey the law 都是守法。","obey 直接接受詞，comply、abide 在這個用法分別要接 with、by。"],
  "113-en-36": ["the＋比較級，the＋比較級","B、C、D 都有前後兩個比較結構：越追求名聲與權力，就越不快樂或越不滿足。","unhappier、less content、less happy 都能表達快樂減少。A 和 E 的前半句沒有正確的比較句型。"],
  "113-en-37": ["despite＋名詞；although＋完整子句","A 用 despite the bad weather；E 用 although the weather is bad。兩句都接活動仍照常舉行。","B 的 having bad weather 容易錯接到主詞 Scout activities；D 的 If only 表但願，並非讓步。"],
  "113-en-38": ["用名詞、形容詞或動名詞表達無法預測","B 用 It’s uncertain whether… 表是否成功仍不確定；D 用 remains unpredictable 說成功與否不可預測。","E 的 There is no predicting whether… 也是慣用句。A 的 There can’t be predicted 缺合適的主詞。"],
  "113-en-39": ["與過去事實相反的假設","A 用 If it had not been for… 搭配 might have made…，表示過去實際有這項建議。","C 用 Without your advice 省去 if 子句，主句仍用 might have made 回推過去結果。"],
  "113-en-40": ["區分預防目的和表達擔心的片語","A 的 to avoid 與 E 的 for fear of 表明目的是避免或擔心意外，for fear of 後可接名詞片語。","原卷也接受 C 的 in case of。它常譯為『以防／若發生……』，自己寫明確的預防目的時用 to avoid 最清楚。D 的 for fear that 後須有完整子句。"],
  "113-ch-1": ["聲、韻、調都要相同","卓與踔都讀 ㄓㄨㄛˊ；「踔厲風發」形容精神振奮、意氣昂揚。","垣／坦是 ㄩㄢˊ／ㄊㄢˇ，滲／摻是 ㄕㄣˋ／ㄔㄢ，陟／涉是 ㄓˋ／ㄕㄜˋ。"],
  "113-ch-2": ["從詞義還原正字","「如臨深淵，如履薄冰」是好像面對深水、踩在薄冰上，形容小心謹慎。「臨」是面對，「履」是踩踏。","A 是「風雨如晦」，B 是「以蠡測海」，D 是「不務正業」。"],
  "113-ch-3": ["把同一個字換成白話比較","D 的「固」都可換成「本來」：本來就難以看透；生在我之前，本來就比我先懂得道理。","A 的因分別有趁著、因為之意；B 的誠是誠心、實在；C 的為是替、向。"],
  "113-ch-4": ["層遞要看同一件事如何逐步加深","梅子由七成落到三成，女子的話也從等待好日子變成盼望現在就來，時間更急迫。","A 的數量變少、語氣變急，兩條線一起推進。B 將泰山、河海與王者並列類比。"],
  "113-ch-5": ["從結句捕捉對功名的態度","「古今將相」最後只剩荒墳，意思是地位再高也留不住。A 說富貴無憑，追逐它又耽誤時光，態度相近。","B、D 有借機上進或施展抱負的意思；C 寫躬耕生活，沒有直接評論功名。"],
  "113-ch-6": ["成語中相同的字也可能有不同意思","「筆酣墨飽」形容筆墨充盈、筆力酣暢；「鸞翔鳳翥」用鳥振翅高飛譬喻書法筆勢飛動。兩者都可形容書法。","滄海一粟是渺小；日就月將是日積月累而有進步；箕踞是伸腿而坐，並非正襟危坐。"],
  "113-ch-7": ["「所以」可表示原因或方法","題句問這酒為何變酸而賣不掉。「先漢所以興隆」也問為何興盛，原因是親近賢臣、遠離小人。","A、C 偏向「用來……的方式或憑藉」，試著改成「之所以」，只有 B 符合題句。"],
  "113-ch-8": ["《詩經》作者多不可考","《詩經》收有不同時代與場合的歌詩，包含民間歌謠、朝廷樂歌、宗廟祭歌，作者身分不全相同。","因此 B 的「皆為文人士大夫，故多可考」不正確。漢代四家詩中完整流傳至今的是毛詩。"],
  "113-ch-9": ["被動句的「於」可翻成「被」","「孟德困於周郎」說曹操受到周瑜圍困，動作施加者是周瑜，符合被動。「孟德」是曹操的字。","「於天地」「於晉」「於秦」在其他選項表示所在、對象或來源。"],
  "113-ch-10": ["記體散文的主旨要看結尾","〈醉翁亭記〉從山水、遊人與宴飲，寫到太守以百姓的快樂為快樂，重心是與民同樂。","〈桃花源記〉隨漁人遭遇敘寫；〈岳陽樓記〉從景物轉入憂樂志趣，不屬滕子京的傳記。"],
  "113-ch-11": ["輓詞要配合亡者身分","「桃李」比喻老師教出的學生，「興悲」寫學生哀悼師長，因此「桃李興悲」適合史可法敬輓恩師。","「貨殖」與商業有關。「坤儀」「蘭摧蕙折」傳統上多見於女輓。"],
  "113-ch-12": ["先找重複句型，再找承接的比喻","首句談自暴，乙以相同句型接上自棄。接著甲、丙依次解釋什麼是自暴和自棄。","最後丁以仁為安宅、以義為正路，末句才有可承接的「安宅」「正路」。順序是乙甲丙丁。"],
  "113-ch-13": ["空格要延續是非顛倒的例子","前文把輕薄的蟬翼視為重、把千鈞視為輕；後文又讓讒人得勢、賢士埋沒。","黃鐘是珍貴的樂鐘，瓦釜是粗陋的陶鍋。丟棄黃鐘卻讓瓦鍋作響，是同一種價值顛倒。"],
  "113-ch-14": ["道家強調順自然、功成不居","「生而不有，為而不恃，功成而弗居」是《老子》式的觀點：有所成就仍不占有、不自恃。","C 的捕魚段出自《孟子》，D 是《論語》教人孝悌仁愛，也屬儒家。"],
  "113-ch-15": ["人物動機要回到文中證據","范增勸項羽對付劉邦，重點是他看見劉邦與昔日不同，認為劉邦志向大、日後會威脅項羽。","A 所說的對范增無禮和安排內奸不是范增起殺機的原文明示原因。其餘三項都合乎該文的勸說或行動。"],
  "113-ch-16": ["菊花意象是秋天與金黃","D 的九月、百花凋落後盛開、滿城如穿黃金甲，是黃巢詠菊的線索。","A、B 是荷花與水面景象；C 的疏影和暗香指梅花。"],
  "113-ch-17": ["分辨作者是否認同孟嘗君得士","甲直接把孟嘗君為相數十年平安歸功於馮諼的計謀，故 D 正確。","乙的「豈足以言得士」明顯是質疑。王安石說「若真得一士，應能制秦」是假設，不是在說已經做到。"],
  "113-ch-18": ["用文類和故事內容雙重判斷","〈虬髯客傳〉是唐傳奇，〈勞山道士〉是《聊齋誌異》的故事，兩篇都是文言短篇小說。","〈漁父〉不屬律賦，〈勸和論〉是勸民和解的文章；〈散戲〉寫戲班，科舉悲劇屬〈孔乙己〉。"],
  "113-ch-19": ["由近到遠要看景物尺度擴張","先是岸邊細草、近旁船桅，再看廣闊平野、天上星月與大江。視線從身邊移到遠方，選 B。","A 從千山萬徑縮向一艘孤舟，方向相反。"],
  "113-ch-20": ["按時代辨認晚唐詞與宋代流派","晚唐、五代的代表詞作多走柔婉細麗一路，例如花間詞的風格。豪放詞風在宋代才由蘇軾等人拓展。","所以誤將晚唐寫成已有『豪放派』大量創作的丙項不正確。"],
  "113-ch-21": ["鄉愁題要找想念的對象","詩用相隔三十年的兩次望月，讓滿月聯想到滿杯鄉色酒和滿懷鄉愁。","C 的征人因蘆管聲一起遠望家鄉，同樣把思鄉連到一個具體景象。"],
  "113-ch-22": ["超然物外要看觀察方式是否轉變","D 將水月與天地分別從『變』和『不變』兩面看，從生命有限轉向物我無盡，表現放寬眼界後的豁達。","A 主要寫月影可愛；B 寫林木；C 甚至寫賞月者希望被人看見。"],
  "113-ch-23": ["用人生轉折辨認魯迅","魯迅曾赴日學醫，後轉向文學，希望從思想與社會層面發聲。〈狂人日記〉等作品與新文化運動時期密切相關。","『棄醫從文』是最有辨識力的關鍵詞。"],
  "113-ch-24": ["用白與塵埃的對立讀立場","屈原用皓皓之白比喻自身清白，用塵埃比喻世俗污染。他寧可赴水，也不願犧牲志節。","這種價值選擇叫擇善固執。通權達變和和光同塵反較接近漁父勸他的處世態度。"],
  "113-ch-25": ["大同理想重點是各年齡層都受照顧","題文寫孩童、成人、長者與弱勢各得其所。C 寫孩童自在歌唱、白髮老人愉快出遊，呈現相近的安樂景象。","A 談治理方法，B 談風氣影響，D 談嚴刑威嚇。題目問的是社會生活畫面。"],
  "113-ch-26": ["用形象與動詞互相檢查","長城是固定在山上的建築，用「蹲踞」有厚重感；「無情」接「冷眼」自然。","縱線、橫線交會後形成四個方向，用「平分」合適；後文明說相遇，所以不能用「錯過」。"],
  "113-ch-27": ["讀因果：頑固不改，最後招致後果","顯者聽見告誡後仍『橫如故』，又把食物定量錯估成還能活多年。病後日夜多食，未滿一年即死。","故事用這個反轉告誡作惡者不能拿壽數當保障，對應『自作孽，不可活』。"],
  "113-ch-28": ["反襯讓一個人物的特徵更突出","一邊寫妻子一再勸、方士直說祿數終點，另一邊寫顯者自以為還有多年，仍舊橫行。","外在勸戒越清楚，越突顯顯者的固執，所以選 D。全文大致按事件順序展開。"],
  "113-ch-29": ["將受字換成「接受」檢驗","公儀休『不受』指不接受別人送的魚。A 的三軍『受』號令，是接受命令，同義。","故事的下人是對人低頭，致魚是送魚過來，不能直接套上其他例句的意思。"],
  "113-ch-30": ["拒絕不當利益才能保有原則","公儀休愛吃魚，仍拒絕贈魚，因接受之後容易欠人情、偏離法度甚至失去官位。","A 的『無欲則剛』強調不為私利所牽制，就能守住原則。公儀休不必放棄吃魚，只要用正當方式取得。"],
  "114-mb-1": ["相同次方可以先除底數","6²⁰＝(6²)¹⁰＝36¹⁰。分母 12¹⁰ 與分子有同樣的指數。","(36/12)¹⁰＝3¹⁰，選 D。"],
  "114-mb-2": ["先整理成 y＝mx＋b","3x＋4y＋5＝0 移項後，4y＝−3x−5。","除以 4 得 y＝−(3/4)x−5/4，斜率是 x 的係數 −3/4。"],
  "114-mb-3": ["√3 的偶數次方是整數","第 n 項是 2(√3)^(n−1)。n−1 為偶數時，(√3)²＝3，可以兩個根號一組配對。","前七項中，第 1、3、5、7 項有理，共 4 項。"],
  "114-mb-4": ["每筆資料加相同數值，離散程度維持不變","每人加 15 分，平均、中位數、眾數也都上升 15 分。","每人的新分數減新平均，結果和原來的分數減原平均一樣，因此標準差不變。"],
  "114-mb-5": ["特殊角的三角函數值","sin 30°＝1/2，cos 45°＝√2/2。cos 120°＝−cos 60°＝−1/2。","原式＝1/2＋√2×(√2/2)−(−1/2)＝2。"],
  "114-mb-6": ["找因式先代入相應的零點","C 的 x＋2 為零時 x＝−2。代入 f，得到 −8−4＋16−4＝0。","依因式定理，除以 x＋2 的餘式為 0，所以 x＋2 是因式。"],
  "114-mb-7": ["封閉路徑在每個經過的頂點都要進出成對","圖上各點最多三條邊。不能重複走邊又要回 A，故每一點只能各進、出一次。","把 B、C、D 的造訪順序排一排，共 3!＝6 種，最後一律回 A。"],
  "114-mb-8": ["乘上單位矩陣，矩陣不變","A 的兩欄可直接由題目讀出：第一欄 (2,4,7)，第二欄 (1,0,6)。","乘欄向量 (1,0) 等於第一欄乘 1、第二欄乘 0，因此 a＋b＋c＝2＋4＋7＝13。"],
  "114-mb-9": ["位移＝方向的單位向量乘距離","v=(−6,8)，長度 √(36＋64)＝10。題目要走 10 單位，位移剛好就是 v。","將位移加到原點 A：(2,−7)＋(−6,8)＝(−4,1)。"],
  "114-mb-10": ["恰一人命中分成兩種互斥情形","只有阿明中為 0.75×0.2＝0.15，只有阿添中為 0.25×0.8＝0.20。","相加得到 0.35。直接乘 0.75×0.8 是兩人都中。"],
  "114-mb-11": ["把絕對值不等式換成區間","|x−√15|＜4 等同 √15−4＜x＜√15＋4。因 3＜√15＜4，範圍左端介於 −1 和 0，右端介於 7 和 8。","整數是 0、1、…、7，共 8 個。"],
  "114-mb-12": ["條件機率固定已知第一次的結果","第一次已是反面，後兩次的四種結果為正正、正反、反正、反反，各等可能。","恰好兩個反面，後兩次必須恰一個反面。正反、反正兩種，機率 2/4＝1/2。"],
  "114-mb-13": ["圓心是直徑兩端點的中點","將 A、B 三個坐標各自平均。x=(1−5)/2＝−2，y=(4＋6)/2＝5，z=(7−3)/2＝2。","所以圓心為 (−2,5,2)。"],
  "114-mb-14": ["開口向下的拋物線，離頂點越近，函數值越大","頂點在 x＝−1，原式距頂點的平方乘上負數。候選 x 為 10、7、−3、−5。","離 −1 的距離依序是 11、8、2、4，最短為 2，所以 f(−3) 最大。"],
  "114-mb-15": ["依遞迴式一項一項往下算","a₃＝a₂−2a₁＝2−2＝0，a₄＝a₃−2a₂＝0−4＝−4。","a₅＝a₄−2a₃＝−4−0＝−4。"],
  "114-mb-16": ["擴充正弦定理：邊長÷對角正弦＝2R","角 C＝180°−87°−48°＝45°，它的對邊 AB＝4√2。","外接圓半徑 R＝4√2/(2sin45°)＝4。"],
  "114-mb-17": ["等比數列的各項往後一格都乘同一公比","把 a₃＋a₅ 的每個加項都往後一格成了 a₄＋a₆。設公比 r，則 r×6＝9。","r＝9/6＝3/2。"],
  "114-mb-18": ["直線與圓相切時，圓心到直線的距離等於半徑","配方得 (x−2)²＋y²＝4−k，圓心 (2,0)。到 3x−4y＝0 的距離為 |6|/√(3²＋4²)＝6/5。","令半徑平方 4−k＝36/25，得到 k＝64/25。"],
  "114-mb-19": ["等差數列奇數項總平均等於中間一項","前七項以 a₄ 為中心，首尾對稱的兩項平均也是 a₄。因此 a₄＝14/7＝2。","a₃ 和 a₅ 離中間同樣遠，故 a₃＋a₅＝2a₄＝4。"],
  "114-mb-20": ["用份數理解兩種機率的比","女生機率是男生的 5/8，可把女生當 5 份、男生當 8 份。","總共 13 份，所以選到女生的機率是 5/13。"],
  "114-mb-21": ["先用基本統計量排除錯項","1 到 9 的平均與中位數都是 5，全距是 9−1＝8，所以 A、B、C 都不對。","9×25%＝2.25，依本題採用規則取下一個位置第 3 筆，值為 3。"],
  "114-mb-22": ["平面向量內積是對應分量乘後相加","u·v＝3×5＋2×(−2)。","15−4＝11。結果是一個數，並非坐標對。"],
  "114-mb-23": ["三次函數以三次項的平移中心判斷對稱中心","令 t＝x−2，整理為 f(x)＝3t³−5t−3。t 改成 −t，前三次與一次項合值會變號。","扣掉常數 −3 後以 t＝0 對稱，所以中心是 (2,−3)。"],
  "114-mb-24": ["期望值是每種獎金乘上機率再相加","總球數 3＋5＋12＝20。藍球機率 3/20，紅球 5/20，黑球無獎金。","每抽期望是 2000×3/20＋1000×5/20＝300＋250＝550。"],
  "114-mb-25": ["向量終點減起點，再按分量算","AB=(1−(−2),3−2)=(3,1)，BC=(3−1,−5−3)=(2,−8)。","2AB−3BC=(6,2)−(6,−24)=(0,26)。"],
  "114-mb-26": ["正比例縮放和平移不改變相關係數","國文人人加 5；英文人人乘 10/9，且沒有成績因截頂而改變規則。","相關係數用標準化後的相對差距來算，這兩種正向線性調整不改變標準化值，所以仍為 0.63。"],
  "114-mb-27": ["先看角度 2x 的範圍","x 由 π/6 到 11π/18，2x 就由 π/3 到 11π/9。","sin 在 π/3 到 π/2 上升，過了 π/2 到 11π/9 下降，因此先增後減。"],
  "114-mb-28": ["依男女出席人數各為 1、2、3 分情況","各一人有 3×4＝12；各兩人有 C(3,2)×C(4,2)＝18。","各三人有 C(3,3)×C(4,3)＝4。加總是 34。"],
  "114-mb-29": ["弧長＝半徑×圓心角（弧度）","圓心角＝10/5＝2 弧度。換算約為 2×180°/π≈114.6°。","與選項比較，120° 最接近。"],
  "114-mb-30": ["條件機率公式","P(A|B)＝P(A∩B)/P(B)。這裡分母用作為條件的 B。","所以 P(A∩B)＝(3/4)(3/8)＝9/32。"],
  "114-mb-31": ["指數函數的底數維持一樣才可能靠平移重合","9×3ˣ＝3²×3ˣ＝3^(x＋2)，因此是將 y＝3ˣ 向左平移 2。","9ˣ＝3^(2x)、3^(5x) 是在改橫向尺度；(1/3)ˣ 的增加方向相反。"],
  "114-mb-32": ["原有五個節目的相對順序固定","從七個時間位置挑兩個給新增節目，有 C(7,2)＝21 種。","兩個新節目不同，可互換次序，有 2 種。總數 21×2＝42。"],
  "114-mb-33": ["對數相加相減對應乘除","2b−a＝2log6−log4＝log(6²/4)。","6²/4＝36/4＝9，所以為 log9。"],
  "114-mb-34": ["矩陣等式逐格對應","左下格 5−2b＝7，得到 b＝−1。左上格 a＋4b＝−1，得 a＝3。","右上格 3＋bc＝1，代 b＝−1 得 c＝2。三個數的和是 4。"],
  "114-mb-35": ["代入直線左式，看正負是否相反","令 F(x,y)＝2x−y−2。A=(5,3) 代入為 5，是正值。","選項 A 在直線上，B、D 代入為正，選項 C 的 (−1,−1) 代入為 −3，故在異側。"],
  "114-mb-36": ["因式分解後用零點劃分符號區間","(x−2)(x²−3x−4)＝(x−2)(x−4)(x＋1)，零點為 −1、2、4。","從最右邊往左，符號依序正、負、正、負。取正值區間 −1＜x＜2 或 x＞4。"],
  "114-mb-37": ["先用抽袋機率求白球來源的權重","甲袋被選機率 1/3，抽到白為 6/10，合起來 1/5。乙袋被選 2/3，抽白為 2/5，合起來 4/15。","已知抽白，甲袋機率是 (1/5)/(1/5＋4/15)＝3/7。"],
  "114-mb-38": ["緯圈半徑為赤道半徑乘緯度的餘弦","北緯 60° 的緯圈周長＝120cos60°＝60 公分。兩點經度差 110°−80°＝30°。","沿緯圈走 30° 只占整圈的 1/12，距離＝60/12＝5 公分。"],
  "114-mb-39": ["反方陣等於自身表示 A²＝I","看 A² 左上格 1＋2a＝1，得 a＝0。再看右上格 2＋2b＝0，得 b＝−1。","因此 a＋b＝−1。其餘兩格也可用 a＝0、b＝−1 驗算。"],
  "114-mb-40": ["俯角配合高度求水平距離","OA＝300/tan45°＝300，OB＝300/tan30°＝300√3。正南和正東互相垂直。","AB＝√(300²＋(300√3)²)＝600 公尺。"],
  "114-ch-1": ["易混字音","『惙』和『啜』都讀 ㄔㄨㄛˋ。危惙指病況危急，啜泣是低聲哭泣。","戧金的『戧』為 ㄑㄧㄤˋ，戕為 ㄑㄧㄤ；淬為 ㄘㄨㄟˋ，晬為 ㄗㄨㄟˋ；櫂為 ㄓㄠˋ，糴為 ㄉㄧˊ。"],
  "114-ch-2": ["同音字要靠詞義辨識","C 的完整詞是餽贈、喟然、潰不成軍，分別是贈送、嘆息和軍隊潰散。","其餘選項至少重複一字。滄海與滄桑都用滄，立錐與錐處囊中都用錐，不脛而走和脛骨都用脛。"],
  "114-ch-3": ["文言的『相』可偏指接受動作的一方","兩句的『相』都可以理解為動作有所指向。『相為言』是為我說話，『相賀』是向人祝賀。","A 的一分別為全、視為相同；B 的向分別是先前、偏向；C 的幸分別是寵幸、有幸。"],
  "114-ch-4": ["依詞義檢查形近字","B 的手舞足蹈、晴天霹靂、愀然變色都寫對。『愀然』可表示神色轉為嚴肅或不安。","A 改『拮据』，C 改『蜚聲』，D 改『自視甚高』。"],
  "114-ch-5": ["成語的褒貶和使用時機","野人獻曝是謙稱個人的意見或心意粗淺，與句中受讚賞後仍自謙相符。","天花亂墜常形容說得過於誇張；庸人自擾指自找煩惱；前仆後繼常形容前人倒下、後人接續奮鬥。"],
  "114-ch-6": ["原卷更正為一律給分","公告將原答案 C 更正為送分，所以這題選任何選項都計分。","練習語境時可先看第一空。下文寫謊言、詐欺與背叛，首空用『正視』可以表達願意面對。其餘兩空還需用整段語氣比對。"],
  "114-ch-7": ["七律排序要看對偶與情緒推進","接在首聯後的是落木下、長江來的對偶景象，依序戊、丙。","再來『萬里／百年』對舉，依序甲、丁。結尾由艱難而白髮，接潦倒停酒，故是乙接末句。"],
  "114-ch-8": ["莊子的養生觀","有涯是有限，無涯是無限。莊子先說拿有限生命去追無限知識會有困境。","後面的『保身、全生、盡年』指順著適當的方法保全生命、享盡天年。讀主旨以後段的正面主張為準。"],
  "114-ch-9": ["借代：用有關聯的事物代稱","題目用『絲竹管絃』代音樂。祝融可代火災，布衣可代平民，兵馬可關聯戰事。","A 的松柏、雞鳴用來比喻在逆境仍守節，沒有像其他項目那樣用關聯名詞代替指定對象。"],
  "114-ch-10": ["同一個字可以有不同詞性","『惡惡臭』第一個惡是厭惡，第二個惡修飾臭，意思是難聞。『好好色』也是用動詞接含形容詞的詞語。","所以 D 不屬於後一個相同字當名詞的例子。B 第二個『樂』指快樂，C 的第二個『親、子』指親人、子女。"],
  "114-ch-11": ["明代章回小說以回目組成長篇故事","長篇敘事按卷回分節，選 D。明代四大奇書通常指《三國演義》《水滸傳》《西遊記》《金瓶梅》。","六朝志怪多簡略記異聞；宋代說話底本的代表為話本，常保留白話特色。"],
  "114-ch-12": ["從典故辨認歷史人物","『醉草清平調』指李白奉詔寫《清平調》；『力士』與高力士相關。D 所配李白正確。","『出師未捷』詠諸葛亮，『語不驚人死不休』是杜甫，洙泗和杏壇則指孔子。"],
  "114-ch-13": ["轉折和遞進的連接語不能混用","『雖然』先承認比賽失利，後面應轉折說付出仍有價值，可接『但是』。","『況且』用來再補一個理由，和『雖然』在此不配。"],
  "114-ch-14": ["事實與主觀評價","C 的房貸政策是事件，稱它為『福音』是作者的價值判斷。","辨別時找『可說是、真可惜、太好』等語句，它們常透露看法。"],
  "114-ch-15": ["作者、作品、文類須同時符合","吳晟〈負荷〉與楊牧〈水之湄〉都是新詩，作者與作品符合臺灣文學脈絡。","洪醒夫〈散戲〉、白先勇〈孽子〉是小說。連橫〈臺灣通史序〉不是小說。"],
  "114-ch-16": ["由意象找思念對象","C 的『鄉書』是寄往家鄉的信，『洛陽邊』又指向家鄉方向。","A 想跟朋友再談文，B 為友人送別，D 寫思念遠行的人。對象不同。"],
  "114-ch-17": ["吃飯比喻實際學習","把食物一口口吃下來才會飽，放到門口只給人看並不能充飢。","把比喻換回為學，朱熹批評的正是把該自己做的功課拿去向外炫耀。"],
  "114-ch-18": ["看詞在句中的位置辨詞性","『一個不完的魘夢』中，魘夢可受數量詞『一個』限制，是名詞。","鼓、引逗、冷去分別表動作或狀態發展。"],
  "114-ch-19": ["郗公欣賞不造作的王羲之","其他年輕人可能因選婿而刻意正襟危坐，唯有東床那位若無其事地坦腹而食。","郗公反覺得此人最好，表現出不隨俗見、能從平常行止看人物。"],
  "114-ch-20": ["理想幻滅要找『再也回不去』的線索","漁人曾標記來路，太守派人依標記尋找，最後仍迷路。","桃花源一度被發現，卻不能再回到那裡，暗示理想境界難以在現實重現。"],
  "114-ch-21": ["期望語氣常用『惟、願、請』","『惟君圖之』是希望您考慮此事。燭之武藉此請秦伯重新衡量攻鄭利害。","A、B 多用反問，D 用『若』先設想一種情況。"],
  "114-ch-22": ["經、史、子、集的常見分類","《道德經》屬道家著作，《世說新語》常列小說家類，兩者都可歸入子部。","《孟子》《左傳》《詩經》在經部；《楚辭》《昭明文選》屬集部。"],
  "114-ch-23": ["婉曲用委婉話語暗示本意","『舅奪母志』字面是舅舅改變母親的意志。由《陳情表》上下文可知是母親改嫁。","不直接說明改嫁，而用奪志表達，因此選 A。"],
  "114-ch-24": ["誇飾故意把事物寫到超過實際","鬢髮用『三千丈』寫，遙遠過往用『五千年春夢』寫，明顯把長度與時間推向極端。","B 將人生比成夢，是譬喻。D 的莊周夢蝶、杜鵑託春心使用典故。"],
  "114-ch-25": ["找出跟原文明確相反的一句","首句說不必追問故事是真是假，重點是透過故事觀照自己。","A 說小說重視故事必須屬實，與原文相反，符合題目要找的『最不適當』。"],
  "114-ch-26": ["側面烘托用他人的反應讓主角特色浮現","D 寫拜倒金大班裙下的人多到數不完，藉旁人的反應呈現她的魅力。","A 直接寫外表與聲音，B 直接寫臉，C 也直接比對外貌特點。"],
  "114-ch-27": ["沿用作者對作品類型的區分","第二段把〈桃花源記〉歸入晉人幻設的寓言一路，指重點在寓意，文詞為末。A 最接近這個分類。","文章比較唐傳奇和古文時說當時論者貶傳奇；宋代平話在市井另行興起，不能概括為擅長改寫唐傳奇。"],
  "114-ch-28": ["兼具奇異情節和宛轉敘述","B 寫筷子投入月光後出現美人，先不滿一尺，落地時變得和常人一樣高，奇事分步展開，畫面具體。","A 主述藥和寶劍，C 主述財物忽然消失，D 主要描寫人物登場，B 最符合題目要的組合。"],
  "114-ch-29": ["以原文的反覆試探定位答案","首段說衛鞅試探秦孝公是否有堅定的變法決心，是否真願意推動強國方案。","最後成為最佳拍檔，關鍵是堅定信念，並非形象或保守。"],
  "114-ch-30": ["利出一孔＝國家只留一條獲利途徑","文中說個人想取得爵位、土地與富貴，就必須走國家設計的軍功途徑。","這與（1）由政府控制並引導人民活動較像。（2）主張個人自由競爭，與『只留一個孔道』不合。"],
  "114-hg-1": ["二戰後基督宗教在部落的傳播","『美國提供救濟物資』是戰後年代線索。傳教、醫療、救濟等活動與原住民族許多家庭或部落改信相連。","荷治時期也有傳教，但題中的美援物資與大規模傳教屬二戰後情境。"],
  "114-hg-2": ["霧社事件後的理蕃政策","1930 年霧社事件後，1931 年總督府的新大綱強調同化教化，並透過集中移住管理。","題幹已提示『教化與同化』，因此不能選恢復以軍事征服為主。"],
  "114-hg-3": ["家庭移民與社會秩序","早期單身男性大量來臺，男女比例不均，定居家庭較少。讓妻小同行可減少這類移民社會的失序風險。","女性也可能參與農務，題幹問政策建議的社會背景，重點在穩定移民社會。"],
  "114-hg-4": ["三省的分工也是制衡","中書擬決策、門下審核、尚書執行。單一高官無法兼掌從擬詔到施行的全流程。","因此可降低權臣把持朝政的機會。三省都是中央機關，並非中央和地方的分層。"],
  "114-hg-5": ["戰後臺灣從進口替代轉向出口擴張","1960 年代國內市場有限，已建立的工業需要更多買家，美援也逐步減少。政府鼓勵工業產品出口。","記為『把生產的商品賣到國外』的出口導向。加工出口區是可連記的例子。"],
  "114-hg-6": ["日治時期社會運動有多條路線","日治知識分子投身文化啟蒙、議會請願與勞工農民運動。題幹同時點到文化和階級。","若只說政治改革或只說激進獨立，都省掉題幹已明示的一部分活動。"],
  "114-hg-7": ["士族與士紳的權力來源不同","魏晉士族依門第血統在中央壟斷或長期掌權。後來的士紳常以功名、家族與地方資源參與治理。","B 同時符合兩期特色。A 將科舉和世襲顛倒。"],
  "114-hg-8": ["用太平天國爆發作年代標記","太平天國於 1851 年起事。題幹說該戰爭在它之前，所以找早於 1851 年的選項。","第一次鴉片戰爭在 1840 年代初；英法聯軍、清法戰爭、甲午戰爭都更晚。"],
  "114-hg-9": ["身分轉向居住地是『在地化』","『過客』仍將目光放在祖國，『在地人』則在居住地建立長期生活和政治、社會認同。","C 符合身分轉變。寄捐款、投資祖國是維繫祖籍地關係的例子。"],
  "114-hg-10": ["哥倫布受西班牙王室資助","『熱納亞人、15 世紀末、女王資助』是哥倫布的線索。1492 年西班牙王室支持他跨大西洋遠航。","他本來想向西抵達亞洲，實際到達加勒比海地區。問資助國，選西班牙。"],
  "114-hg-11": ["南丁格爾與克里米亞戰爭","1850 年代克里米亞戰爭中，南丁格爾投入傷兵照護，重視消毒、環境衛生與病房管理。","她的改革與近代護理制度相連。一次世界大戰的年代比她服務該戰的年代晚很多。"],
  "114-hg-12": ["浪漫主義重感情、歷史與想像","題幹欣賞中古的宗教熱情、騎士冒險，符合 19 世紀浪漫主義對中世紀的回望。","啟蒙時代常重視理性與批判。遇到感情、傳說、個人想像，要想到浪漫主義。"],
  "114-hg-13": ["俄國內戰的戰時共產主義","布爾什維克十月革命後，蘇維埃政權在內戰階段強制徵糧，用以維持軍隊和城市供應。","十月革命實際在 1917 年，內戰與戰時共產政策在 1918 年後展開。題目要辨認的是蘇維埃政權。"],
  "114-hg-14": ["米蘭敕令使基督教合法化","西元 313 年後，基督徒可合法信仰，並獲得原先被沒收財產的返還。","合法化與定為國教是不同階段。羅馬帝國將基督教定為國教在後來。"],
  "114-hg-15": ["自然災害影響南北經濟重心","黃河決溢改道，先影響北方農田、道路與人口生活；戰亂與遷移進一步削弱北方。","南方在移民、開發與經濟擴張下相對興起，與中國歷史上經濟重心南移相符。"],
  "114-hg-16": ["由甘蔗判斷熱帶商業性栽培","甘蔗適合溫暖潮濕環境，通常大規模種植，接著製糖加工並進入市場。","從流程圖辨認以經濟作物為主、搭配加工或銷售的模式，符合 A。"],
  "114-hg-17": ["巴西嘉年華辨識國家","嘉年華是巴西著名民俗活動，里約熱內盧尤其有名。移民與非裔文化共同形成巴西多元文化。","金磚五國中的其餘選項也有多元族群，但『嘉年華』是最能縮小範圍的線索。"],
  "114-hg-18": ["由人口金字塔突出位置辨認移工","圖形突出的是勞動年齡層，且性別結構不均，因此最容易想到某性別的成年勞工大量移入。","若是重男輕女影響出生，差異會先出現在底部的嬰幼兒年齡層。"],
  "114-hg-19": ["高齡化階段的三個門檻","65 歲以上占 7% 為高齡化、14% 為高齡、20% 為超高齡。題中的 19.18% 落在 14% 和 20% 間。","題目問『邁向』哪個階段，所以依更正答案選 C，表示正接近超高齡社會的 20% 門檻。"],
  "114-hg-20": ["巴爾幹半島的國家分屬不同區域組織","一些巴爾幹國家加入歐盟，另一些未加入，所以跨境追查可能遇到不同的司法與警務合作機制。","這題依更正答案選 D。題目問加入狀況差異大的地區，要比較同一半島內的多個國家。"],
  "114-hg-21": ["澳洲西部為古老岩地高原","澳洲西部廣大高地以古老結晶岩和乾燥地貌為特色。東部大分水嶺也不能讀成新褶曲高山。","紐西蘭的著名峽灣在南島西南，火山地形則以北島較著名。"],
  "114-hg-22": ["寮國水力發電與跨境售電","寮國臨湄公河，山地與河川落差有利水力發電，電力外售泰國、越南等鄰國。","『東南亞的電池』指這種跨國供電定位。"],
  "114-hg-23": ["建蔽率看占地，容積率看各層樓地板面積合計","A 假設各層同面積，占地 30%≤35%，四層合計 30%×4＝120%，並為住宅用途。","B、D 的占地超過限制。C 面積雖合規，題目給的是住宅區，選項 A 的用途最符合題意。"],
  "114-hg-24": ["同一零件採共同尺寸與接口＝規格化","不同品牌都改用 Type C，重點是插頭形制與接口能互通。依題意最具體的是規格化。","標準化是較廣的概念。專業化指分工，客製化則依個別需求改做。"],
  "114-hg-25": ["殖民邊界常忽略原有族群分布","殖民強權畫出的界線可能切開同一族群，也可能把關係緊張的多個群體包進一國，留下治理難題。","題目問廣泛的結構原因，選與殖民邊界直接相關的 C。"],
  "114-hg-26": ["伯吉斯同心圓的過渡帶","低收入住戶和新移民常進入緊貼中央商業區的過渡帶，原住戶外移，土地使用與居住條件較不穩定。","讀圖時從中心看。這幅圖中心標 5，外面第一圈標 4，所以選 B。"],
  "114-hg-27": ["拉丁美洲裔在美國南部與西南突出","觀察美墨邊境附近的加州、德州、新墨西哥一帶。圖乙在這些區域色階集中。","圖丙高值主要在美國東南部，分布重心不同。"],
  "114-hg-28": ["大西洋三角貿易要順著箭頭讀","甲由非洲到美洲，主要運送被奴役者；乙美洲到歐洲，常載糖等熱帶作物。","丙由歐洲到非洲，運送槍枝等商品，因此順序是奴隸、熱帶作物、槍枝。"],
  "114-hg-29": ["地勢會決定水往哪裡流與積在哪裡","依給定的降水量模擬淹水，需要知道高程、坡度與低窪地形，可用地勢分析。","環域分析主要找指定距離內的範圍；查詢分析是選取符合條件的資料。"],
  "114-hg-30": ["賽普勒斯北部由土耳其支持","賽普勒斯島北部土裔社群在土耳其支持下建立北賽普勒斯政權。南部主要是希裔社群。","題目問北部的支持者，選土耳其。希臘容易與南部的希裔背景混淆。"],
  "114-hg-31": ["1914 年非洲仍獨立的少數國家","衣索比亞抵抗義大利殖民入侵，賴比瑞亞也維持獨立，所以選 A、D。","納米比亞曾屬德國殖民地，塞內加爾屬法國勢力，烏干達受英國控制。"],
  "114-hg-32": ["1857 年印度兵變的宗教導火線","士兵需咬破彈藥包，傳聞潤滑劑有牛油、豬油，分別觸犯印度教與伊斯蘭教禁忌。A、C、E 從政策、導火線與文化差異說明。","事件後英國政府加強直接統治。殖民剝削是背景，但題目強調的直接引爆原因是宗教與文化衝突。"],
  "114-hg-33": ["原住民族復振來自民權運動與政策變化","原住民族權益較受媒體和社會重視，與民權、人權運動及各種政府、國際政策進展相關，選 A、B、D、E。","C 的『各國普遍承認集體自決』範圍過廣，實際進展因國家而異。"],
  "114-hg-34": ["哥倫布大交換分清楚傳播方向","美洲原住民受外來疾病重創，基督宗教和馬牛由歐洲進入美洲，馬鈴薯由美洲傳往歐洲，所以 A、B、C、D 可選。","火雞原產美洲，後來傳到歐洲，E 的方向顛倒。"],
  "114-hg-35": ["文藝復興以人文與新技法重讀古典","義大利率先興起，人物情感更細緻，透視和解剖讓繪畫更自然，選 A、C、E。","文藝復興汲取古希臘、羅馬傳統，也重視素描及構圖，排除 B、D。"],
  "114-hg-36": ["臺灣地名中的地形字","崙可指沙丘等隆起地形，澳常指灣澳，鼻常指突入海中的岬角，因此選 A、B、C。","崎常聯想到坡陡處；坑多指低陷地形，與題中『平原』配對不合。"],
  "114-hg-37": ["剩水區是降水超過蒸發的區域","赤道附近間熱帶輻合促進上升降雨，中高緯有盛行西風及極圈附近的氣旋活動，對應 A、C、D。","位於副熱帶的馬緯度無風帶常有下沉氣流、降水少，是缺水的典型區域。"],
  "114-hg-38": ["由形成機制辨臺灣火山地景","澎湖以基性玄武岩為主，基隆山可由侵入岩理解，大屯及龜山島的岩漿、噴發型態依題目分類為 D、E，故選 A、B、D、E。","小琉球以隆起珊瑚礁石灰岩為主，C 說是寧靜式噴發形成，地質成因不對。"],
  "114-hg-39": ["殖民史與東南亞的宗教分布","菲律賓的天主教傳統與西班牙有關，東帝汶則深受葡萄牙影響，選 B、C。","泰國以佛教較普遍，印尼主要信奉伊斯蘭教，越南的宗教結構則更多元。"],
  "114-hg-40": ["季風影響常帶來夏雨冬乾","高雄、曼谷、孟買都受季風型季節降雨影響，夏半年較多雨，冬季偏乾，選 A、B、E。","洛杉磯屬典型冬雨夏乾的地中海型；倫敦較少出現明顯冬乾。"],
  "114-en-1": ["brief＝短暫的","雲霄飛車到了頂端後就往下衝，中間只有短暫的停頓。a brief pause 是『短暫的停頓』。","tasty 好吃的，local 當地的，mental 心智的。"],
  "114-en-2": ["much to my relief＝令我大大鬆一口氣","父親輕度中風後很快康復，說話者感到寬心，所以選 relief。","injury 傷害、stress 壓力、sweat 汗水，都不符合得知家人康復的心情。"],
  "114-en-3": ["casual＝休閒的、不正式的","原句直接用 or informal 解釋空格。T 恤和牛仔褲屬較不正式的穿搭。","swift 快速的，temporary 暫時的，permanent 永久的。"],
  "114-en-4": ["element＝構成要素","such as 後舉出大團圓、討喜主角、背景音樂，它們都是浪漫喜劇的元素。","leather 皮革，column 柱或專欄，helmet 安全帽。"],
  "114-en-5": ["within walking distance＝步行可達","商店和餐廳離家不遠，走路就能到。distance 是距離。","記為一組固定搭配。tolerance 容忍，conference 會議，evidence 證據。"],
  "114-en-6": ["recognize＝認出","歌手戴面具，聽眾仍能靠獨特嗓音認出他。recognize 可直接接人。","rely 常搭 on，relay 指轉達或接力，reduce 指降低。"],
  "114-en-7": ["analyze＝分析","研究者先細看消費者行為，之後才針對資料提出行銷建議。closely analyzed 是仔細分析。","retain 保有，reject 拒絕，apologize 道歉。"],
  "114-en-8": ["destructive＝破壞力強的","海嘯將船沖上岸，城鎮成了碎屑，這些都是破壞力的表現。","constructive 是有建設性的，imaginative 是有想像力的，sensitive 是敏感的。"],
  "114-en-9": ["transfer money to an account＝把錢匯到帳戶","con artist 是騙子，陌生人的帳戶是款項的去向。transfer 主詞是匯款的人。","vanish 消失，accomplish 完成，convert 轉換性質或形式。"],
  "114-en-10": ["figure out＝想出、弄懂","老闆在經濟危機中想出促銷方法，後半句的 his plan 呼應想出來的方法。","pass away 過世，pull over 靠邊停，calm down 冷靜。"],
  "114-en-11": ["keep track of＝持續留意","父母需要追蹤孩子上網情況，才能確認瀏覽內容適合。","lose control of 是失去控制，come down with 是染上疾病，put up with 是忍受。"],
  "114-en-12": ["draw in＝吸引","景點開幕後持續吸引世界各地遊客。has been 後面接 drawing in，表示動作一直持續。","put off 延後或使反感，take after 長得像，break out 爆發。"],
  "114-en-13": ["on behalf of＝代表","學生會主席以學生會的名義宣布募款活動，因此選 On behalf of。","in addition to 除了……以外，as opposed to 與……相對，by virtue of 憑藉。"],
  "114-en-14": ["in turn＝進而、接著導致","先有景氣衰退，接著影響就業，後者是前者引發的結果。","at random 隨機，at ease 放鬆，in vain 徒勞。"],
  "114-en-15": ["go the extra mile＝比基本要求更努力","想進頂尖大學要參與課外活動又維持成績，這是多付出一點的具體例子。","spill the beans 洩漏祕密，let out a scream 尖叫，beat around the bush 拐彎抹角。"],
  "114-en-16": ["過去完成式 had＋過去分詞","抵達機場是過去事件，班機起飛發生在抵達之前，所以用 had taken off。","現在完成式 has taken off 是站在現在回看，這裡的比較基準是過去的抵達時間。"],
  "114-en-17": ["mustn’t＝禁止","這個停車位置只留給緊急車輛，所以普通車輛不得停。","may 表示許可，wouldn’t 可指不願或假設中不會，都不如 mustn’t 直接表達規定。"],
  "114-en-18": ["recommend doing＝建議做某事","recommended 後面若直接接動作，用 V-ing。句意是建議每天複習單字。","另一種正確構造是 recommend that＋主詞＋原形。此題沒有 that，所以選 reviewing。"],
  "114-en-19": ["介系詞＋whom 指人","把關係句拆回 I spoke to the manager during the meeting。spoke 要用 to 介紹談話對象。","將 to 提到 whom 前，得到 the manager, to whom I spoke。which 通常指物。"],
  "114-en-20": ["thought-provoking＝引人深思的","後面說演講鼓勵學生批判思考，表示演講引發思考。","provoking 有主動引起的意思。整個複合形容詞放在 lecture 前，常用連字號。"],
  "114-en-21": ["過去分詞可補充說明主詞","真正主動詞是 studied。中間的 motivated by… 表示聽到鼓舞的話而受到激勵。","若寫 were motivated，會在同一句放兩個限定動詞，中間卻缺少連接。"],
  "114-en-22": ["leave＋受詞＋形容詞＝使某人處於某狀態","活動取消，使遠道而來的客人感到失望。leave guests disappointed 符合語意與句型。","disappointed 描述人的感受，disappointing 則形容令人失望的事物。"],
  "114-en-23": ["間接問句使用正常語序，也可用疑問詞＋to V","how to get to the gym 是『怎麼到體育館』，可接在 Can you tell me 後面。","A、B 像直接問句般倒裝；C 的 what 已代表要做的事，又加 it 會重複。"],
  "114-en-24": ["數量詞＋of whom 引導補充說明","three sons 有三人，所以可用 all of whom（他們三人都……）。","both 只指兩人。A、D 直接用 them 開新句，但前面只有逗號，缺連接詞或句號。"],
  "114-en-25": ["Seeing 開頭表示主詞看到後的反應","Nina 看見蟑螂跑過桌面，所以尖叫。Seeing 的動作主體和主句的 Nina 一致。","see＋受詞＋原形可表觀察到完整動作，故 seeing the cockroach run 合適。"],
  "114-en-26": ["主旨要涵蓋整篇","文章一路從葡萄品種的起源、交易、種植難題講到其地位和藝術影響。","C 的 trace the historical importance 概括整體。種植和宗教只是其中個別段落。"],
  "114-en-27": ["辨代稱要把指涉對象代回去","the choice of emperors、the precious fruit、this ancient grape variety 都在不同句子指同一種葡萄。","divine abundance 是葡萄所象徵的意義，the distinctive oval shape 只是它的形狀。"],
  "114-en-28": ["細節題找兩條可對照的證據","宴會展示葡萄，說明它是奢侈食材。柱頭、裝飾雕帶上的葡萄圖案，說明它也是藝術題材。","B 把兩點都說到。原文的 grape houses 用來儲藏水果，沒有說主要用於發酵。"],
  "114-en-29": ["command a price＝賣到某個價位","後面以一串葡萄可賣相當於 3,000 美元為例，所以 command 指配得上、能賣得高價。","D deserved 是四項中最接近的。此處不是『下令』，用 fetch a high price 也能理解。"],
  "114-en-30": ["客觀語氣重在描述和舉例","作者以背景、價格、貿易、藝術等內容說明葡萄的地位，整體沒有嘲笑、批判或質疑的立場。","objective 是客觀的；critical、skeptical、humorous 分別是批判、懷疑、幽默。"],
  "114-en-31": ["成立機構可用 found、establish、set up","三者都能直接接 a charity，表示成立慈善機構。found 在這裡是原形，意思是創立。","participate 表示參與，通常接 in；make up 常表示組成、編造或補足，不適合這裡。"],
  "114-en-32": ["表示有關聯可用 be linked to 與 be associated with","題目在描述社群媒體使用與青少年壓力、焦慮程度的關聯，C、E 都自然。","be devoted to 是致力於，be exposed to 是暴露於，be satisfied with 是對……滿意。"],
  "114-en-33": ["讓步介系詞 despite / in spite of＋名詞片語","his lack of experience 是名詞片語，後半句寫即使欠缺經驗，他仍得第一。A、E 都接得上。","although 和 while 此用法通常接有主詞、動詞的子句；unless 意思是除非。"],
  "114-en-34": ["用同義詞辨認揶揄、嘲弄","tease、ridicule、make fun of 都能表示拿政治人物開玩笑，符合觀眾大笑。","forbid 是禁止，take delight in 指以……為樂，未直接表達表演者嘲弄的動作。"],
  "114-en-35": ["三種『由……組成』的句型","委員會由不同領域專家組成，可用 consists of、is composed of、is made up of。","若用主動 make up，主詞應是組成委員會的成員。be capable of 是有能力做某事。"],
  "114-en-36": ["as long as＝只要","A 用 Nothing is impossible，E 用 Anything is possible，正反表達都可以接 as long as you study hard。","hard 在 study hard 是努力地；hardly 是幾乎不。其餘句子有名詞或子句結構問題。"],
  "114-en-37": ["與過去事實相反的假設句","條件用 if＋had＋過去分詞，結果用 wouldn’t have＋過去分詞，所以 D 成立。","B 用 Had I known 倒裝，等於 If I had known。C 改成與現在情況相反的形式，少了過去結果。"],
  "114-en-38": ["so＋副詞＋that 表示『如此……以至於』","A 用 was written 做被動，needed to be rewritten 表示報告需要被重寫。E 用 required a complete rewrite 表達同義結果。","B 變成『我們需要被重寫』，C 誤用主動，D 把語意改成『太草率而無法完全重寫』。"],
  "114-en-39": ["the＋比較級，the＋比較級","B 用 The longer… , the more likely you are to…；E 用 The more time you spend… , the more likely you are to…，都能表達時間越長越可能買。","時間由人 spend，不能寫成 you cost time。more likely 搭配 be likely to＋原形。"],
  "114-en-40": ["no matter how / however＋副詞＋主詞＋動詞","C 的 No matter how hard he tried 與 D 的 However hard he tried 都表示『無論他多努力』。","這是讓步副詞子句，主詞 he 在 tried 前。A 的 did he try 是疑問句倒裝，不適用。"],
  "115-hg-1": ["送王船與王爺信仰","題幹最有辨識力的是『燒王船』，民間藉送王船象徵把瘟疫和災厄送出境，與王爺信仰密切相關。","保生大帝也和醫藥、治病有關，但辨認這種祭典要抓『王船』；媽祖主要與航海守護相關。"],
  "115-hg-2": ["蘇聯末期的戈巴契夫改革","1989 年、國會改革、由一黨專政走向多黨，以及對西方緩和，是蘇聯末期的關鍵線索。","戈巴契夫推動改革與公開化，但經濟困難未立刻解決。鄧小平改革開放的重心在中國的經濟改革。"],
  "115-hg-3": ["以航海路線辨識殖民國","『通過太平洋來到東亞』指向西班牙跨太平洋的航線。西班牙從美洲出發跨洋抵菲律賓，並與他國競逐香料貿易。","葡萄牙的典型路線是繞非洲好望角、經印度洋往東。香料本身四國都有興趣，航線才是關鍵。"],
  "115-hg-4": ["塞爾柱突厥與拜占庭","11 世紀進入巴格達、使哈里發受制，接著擊敗拜占庭並進入小亞細亞，符合塞爾柱突厥。","蒙古軍攻入巴格達發生於 13 世紀。先用世紀排除，再看地點。"],
  "115-hg-5": ["東晉門閥政治","世家大族掌握人脈、財力、文化聲望和軍事資源，東晉司馬氏皇權需要依賴這些大族。","像王氏、謝氏都曾居政治要津。題幹強調的是世家大族長期與皇權制衡。"],
  "115-hg-6": ["第一次臺海危機與中美共同防禦條約","韓戰結束後，東亞進入同盟布局。1954 年中共砲擊金門，臺海情勢升高。","同年中華民國與美國簽訂《中美共同防禦條約》。注意 1954 年砲擊與 1958 年八二三砲戰可分屬不同次危機。"],
  "115-hg-7": ["文藝復興的人文主義","重視個性、人的思想情感和現世生活，是文藝復興人文主義的特色。","題幹特別說仍可接受基督信仰。人文主義重估人的價值，當時許多思想家仍是基督徒。"],
  "115-hg-8": ["臺灣議會設置請願運動","『立法權、預算審查權』描述的是議會。『向日本帝國議會請願』點出爭取臺灣議會的途徑。","臺灣文化協會、臺灣民眾黨是日治時期的團體，但題目所求是具有上述權力的自治機構。"],
  "115-hg-9": ["用美國南北戰爭推算日本史年代","美國南北戰爭在 1865 年結束，戰後重建和日本 1868 年左右展開的明治維新時間相符。","甲午戰爭在 1894 年開打，偷襲珍珠港在 1941 年。把外國事件當作年代尺。"],
  "115-hg-10": ["婦女選舉權運動","紐約州塞尼卡瀑布 1848 年婦女權利大會主張包含婦女選舉權。1848 年屬 19 世紀中葉。","題目問這種運動訴求何時出現。美國憲法第十九條修正案在 1920 年生效，是後來的成果。"],
  "115-hg-11": ["排灣族的家屋與百步蛇紋","板岩家屋加上貴族階序、百步蛇祖靈意象，指向排灣族。","單看板岩屋，也可能聯想到其他族群；將蛇紋和貴族象徵一起比對更可靠。"],
  "115-hg-12": ["由徽章聯想到飛虎隊","辨識原圖的飛虎隊意象。抗日戰爭時，美國志願航空隊曾協助中國迎戰日軍。","北伐是國民政府早期的軍事統一行動，冷戰中的臺海危機則在二戰之後。"],
  "115-hg-13": ["十字軍東征與地中海商業","11 世紀末十字軍東征開始，軍隊和物資需要跨海運送，義大利商人藉勢擴張東地中海商業據點。","威尼斯、熱那亞、比薩是這題的港市線索。亞歷山大東征與布匿戰爭都在古代。"],
  "115-hg-14": ["均田制瓦解後的兩稅法","『戶籍散亂、土地兼併』說明按人丁及授田運作的租庸調制度難以為繼。","唐代改行兩稅法，依資產與土地等課徵，於夏秋分徵。明代一條鞭、清代攤丁入畝都是其他時期的改革。"],
  "115-hg-15": ["德意志帝國的世界政策","『20 世紀初、世界政策』是威廉二世時期德國追求海外勢力、海權和殖民地的線索。","德國海軍擴張使英國感受到威脅。不要只看某國經濟強大，還要辨認政策名稱。"],
  "115-hg-16": ["戰後初期的長官公署","『內地來臺警官』領導、臺籍作基層，配合後續拔擢臺籍，指向 1945 年政權移交後及二二八事件前後。","1940 年代的行政長官公署符合這個時間。1880 年代仍是清治，1920 年代仍是日治。"],
  "115-hg-17": ["二戰後的非殖民化","戰後歐洲殖民列強受到削弱，亞洲、非洲民族獨立運動大增；社會主義陣營亦擴張。","一戰後已有民族自決的訴求，但題幹描寫亞非太平洋廣泛脫離殖民的浪潮，更符合二戰後。"],
  "115-hg-18": ["湖廣地區成為糧食主產地","明代後期湖廣稻米產量提高，形成『湖廣熟，天下足』的說法，能透過運輸供糧。","這裡的湖廣主要對應今天的湖北、湖南。看見『供應全國糧食』要把地名與農業變化連在一起。"],
  "115-hg-19": ["清代中部拓墾與割地換水","張達京在臺中開發水圳，與當地原住民透過割地換水協調分配灌溉，題幹的分水做法指向這一帶。","可連記彰化施世榜與八堡圳、鳳山曹謹與曹公圳、台北郭錫瑠與瑠公圳。"],
  "115-hg-20": ["延邊位在中國東北與朝鮮半島交界一帶","吉林東部鄰近北韓，延邊是朝鮮族自治州，歷史上有朝鮮半島移民，保有朝鮮語和相關文化。","位置與族名兩條線索都指向朝鮮人。"],
  "115-hg-21": ["由地形、降水和板塊判斷能源","紐西蘭山地多，河川落差大，適合水力發電；北島部分地區有火山與地熱資源。","因此合適的組合是水力、地熱。核能不屬再生能源，也不是該國主要電力。"],
  "115-hg-22": ["嬰兒性別比＝每 100 名女嬰對應的男嬰數","高於 110 表示男嬰格外多。題目問的是出生時期，先排除成人遷移或戰爭造成的成年人口差異。","傳統偏好男孩可能影響生育選擇，與這種出生人口差異最直接相關。"],
  "115-hg-23": ["河流向下侵蝕形成峽谷","太魯閣的立霧溪向下切入岩層，留下狹窄谷底和陡峭兩壁。","比較侵蝕與堆積：侵蝕搬走岩石並加深谷地；堆積把沉積物留在原地，通常不會切出深谷。"],
  "115-hg-24": ["出生下降會提高老年人口的比重","一胎化長期壓低出生數，令年輕人口變少，而原有的大批人口逐步變老。","醫療進步與死亡率下降可延長壽命，題目問快速老化最主要的政策性因素，選一胎化。"],
  "115-hg-25": ["人口金字塔從高年齡層讀壽命線索","比較兩圖時看上端。2018 年高年齡層分布較明顯，顯示更多人活到高齡。","所以平均壽命延長。只看某個年齡層寬窄，無法直接斷定移入勞工增加。"],
  "115-hg-26": ["比例尺先把單位統一","32 公里＝32×100,000＝3,200,000 公分。圖上 16 公分對應實際 3,200,000 公分。","兩邊同除 16，得到 1：200,000。"],
  "115-hg-27": ["認雪梨港地標","選 A，留意白色帆狀屋頂。雪梨歌劇院位於雪梨港，是辨識澳洲雪梨常用的地標。","做照片題時先找建築和地形，例如海港、橋梁及地標，再判斷城市。"],
  "115-hg-28": ["由年代與區域判讀經濟事件","題幹同時給『2010 年』、『西班牙』、『財政危機』，符合 2010 年前後的歐洲債務危機。","亞洲金融風暴主要關聯 1997 年亞洲市場，石油危機典型年代是 1970 年代。"],
  "115-hg-29": ["辨認國道 5 號","雪山隧道位於北宜高速公路，其路線是國道 5 號，連接臺北、新北與宜蘭。","看原圖要找國道盾牌上的 5，並用坪林、頭城及雪山隧道交叉確認。"],
  "115-hg-30": ["苗栗公館與客家醃菜","福菜以芥菜醃漬，是臺灣客家常見的傳統食物。苗栗公館有相應的客家聚落與飲食文化。","『福菜、踏鹹菜』是比『苗栗』更直接的線索。"],
  "115-hg-31": ["由季節景觀判斷緯度與氣候","冬季白雪、春花、秋楓，加上夏季可能受颱風影響，四季分明且位於東亞。","北海道冬季明顯有雪；沖繩、香港與峇里島的低海拔地區不具這種雪季。"],
  "115-hg-32": ["都市化也可能由農村推力造成","工作不足、貧窮與土地分配問題，促使居民離開農村而進入大城，都市人口比率因而上升。","都市人口占比是居民住在哪裡的指標，不能直接推成國家富裕。"],
  "115-hg-33": ["新加坡接近赤道，全年高溫、多雨","讀氣候圖先看溫度曲線：月均溫高、全年變化小。再看降水柱：每月有雨，沒有很明顯的乾季。","符合上述熱帶雨林型特徵的是圖 A。"],
  "115-hg-34": ["山地的垂直氣候帶","同一地點隨海拔上升，氣溫逐漸下降。臺灣由海平面到高山有很大高度落差，因而出現多種氣候與林相。","坡度是地面陡緩，海拔高度才是這題的主要控制因素。"],
  "115-hg-35": ["生產流程前後階段由不同公司負責＝垂直分工","晶片設計、晶圓製造及封裝測試是前後不同的生產環節。各公司專注在各自環節，就叫垂直分工。","若一家企業合併控制前後環節，才是垂直整合。水平則指同一階段。"],
  "115-hg-36": ["臺南濕地與黑面琵鷺","黑面琵鷺在臺灣西南沿海的魚塭、潟湖與泥灘度冬。台江國家公園包括臺南曾文溪口等濕地。","玉山以高山生態為主。題目關鍵是渡冬水鳥與沿海國際級濕地。"],
  "115-hg-37": ["相同距離內，氣壓差越大，風力通常越強","四組 A 到 B 都是 1 公里。逐組讀兩點的等壓線數值並看差值，D 的氣壓梯度最大。","不要比較哪組的最高氣壓數字最大。要比較每單位距離的氣壓變化。"],
  "115-hg-38": ["乾燥地區建築常用小窗","沙漠白天日照強，也可能有風沙。小窗可減少進入室內的日照和沙塵。","高腳屋與斜屋頂常見於較濕、較常降雨或有淹水風險的地區。"],
  "115-hg-39": ["火耕煙霧飄散造成霾害","大量燃燒釋出細粒懸浮微粒，隨風到鄰國形成灰霧、降低能見度並損害空氣品質。","沙塵暴主因是沙塵揚起。這題的污染源是火耕煙霧，選霾害。"],
  "115-hg-40": ["五大湖區酪農帶","五大湖附近較涼，生長季短，但都市多、交通便利。生乳等易腐產品需要快速抵達市場，因而利於酪農。","美國中部大平原常連結小麥或畜牧，密西西比河下游則較暖，與題幹線索有別。"],
  "115-mb-1": ["斜率＝往上變多少 ÷ 向右走多少","由 A 到 B，x 增加 5−1＝4，y 變成 2−3＝−1。","斜率是 −1/4。若從 B 算回 A，分子分母要同時換順序，結果一樣。"],
  "115-mb-2": ["一次式除法的餘式定理","2x＋1＝0 時 x＝−1/2。把這個 x 代進 f，商乘除式的部分會變成零。","餘式＝2(−1/2)³＋3(−1/2)²−1＝−1/4＋3/4−1＝−1/2。"],
  "115-mb-3": ["絕對值表示距離","|x＋2|＜4 表示 x＋2 距離零不到 4，所以 −4＜x＋2＜4。","三邊都減 2，得到 −6＜x＜2。嚴格小於，兩個端點都要用小括號。"],
  "115-mb-4": ["圓的標準式","把 x²−4x 配成 (x−2)²−4，y²＋6y 配成 (y＋3)²−9。","整理得到 (x−2)²＋(y＋3)²＝25。比對 (x−h)²＋(y−k)²＝r²，圓心是 (2,−3)。"],
  "115-mb-5": ["互補的兩個銳角","67°＋23°＝90°。在直角三角形，一個銳角的鄰邊是另一角的對邊。","cos 67°＝sin 23°＝x。"],
  "115-mb-6": ["同位置的矩陣元素相減","把 A 移到右邊，B＝2I−A。2I 的兩個對角元素是 2，其他是 0。","第一列是 2−1＝1、0−5＝−5；第二列是 0−2＝−2、2−3＝−1。"],
  "115-mb-7": ["對數相減對應相除","log a−log b＝3.1−1.1＝2，所以 log(a/b)＝2。","常用對數底數是 10，a/b＝10²＝100，因此 a＝100b。"],
  "115-mb-8": ["同底數時比較指數","把 4 寫成 2²，得到 x＝2^0.6，y＝2^0.4。","xy＝2^1，x²＝2^1.2。底數 2 大於 1，指數最大的 x² 數值也最大。"],
  "115-mb-9": ["遞迴式化為等比數列","3aₙ₊₁＋aₙ＝0，所以每往下一項乘 −1/3。","從第 2 項到第 5 項有 3 次乘法。a₅＝(−4/3)(−1/3)³＝4/81。"],
  "115-mb-10": ["列出等可能的數對","從四個數任取兩個，順序無關，共有 4×3÷2＝6 對。","差的絕對值為 2 只有 {1,3} 與 {2,4}，機率是 2/6＝1/3。"],
  "115-mb-11": ["等差數列求項數與總和","從 35 到 100 共增加 65，每天多做 5 下，所以有 13 次增加，包含首日共有 14 天。","平均每天 (35＋100)÷2＝67.5 下，總數 67.5×14＝945。"],
  "115-mb-12": ["配方法找二次式的最小值","x²＋4x＋5＝(x＋2)²＋1。平方最低是零，所以整式最小為 1。","任何實數 x 代入都大於等於 0。"],
  "115-mb-13": ["分數指數與平均數","3^(3/2)＝3√3，3^(5/2)＝9√3，3^(7/2)＝27√3。","三個數加起來再除以 3，得到 (3＋9＋27)√3÷3＝13√3。"],
  "115-mb-14": ["百分位數要找排序位置","資料已排序，共 30 人。30×65%＝19.5，依本題採用的規則取下一個整數位置 20。","第 19 筆是 38，第 20 筆是 40，所以第 65 百分位數是 40。"],
  "115-mb-15": ["同時間內，距離與速度成正比","沿經線往北極走，甲從北緯 20° 到 90°，經過 70° 的圓弧。","甲速度是乙的兩倍，同時到達表示乙只走 35°。向北走 35° 到 90°，出發處是北緯 55°。"],
  "115-mb-16": ["時針轉一圈需 12 小時","晚上 11 點到早上 7 點共 8 小時。時針每小時走 360°÷12＝30°。","共轉 240°，換成弧度是 240÷180×π＝4π/3。"],
  "115-mb-17": ["共線向量要看方向和長度","取向右為正，設 AB＝1 個單位。AC 向右 1＋2＝3 單位，DC 向左 3 單位。","所以 AC＋DC 為零向量。BA 向左，BC 向右，兩者方向相反。"],
  "115-mb-18": ["內積＝對應分量乘積相加","設 A=(0,0)、B=(2,0)、D=(0,2)、C=(2,2)。E 是 CD 中點，所以 E=(1,2)。","AE=(1,2)，DB=(2,−2)，內積＝1×2＋2×(−2)＝−2。"],
  "115-mb-19": ["同主題相鄰，用捆綁法","將防火、防震、防空各當一大組，組的順序有 3!＝6 種。","每組內各自重排，總數為 3!×2!×2!×3!＝144。"],
  "115-mb-20": ["期望值＝金額乘機率再相加","3 枚公正硬幣有 8 種等可能結果。3 正面有 1 種，2 正面有 3 種，其餘 4 種。","平均＝3000×1/8＋1200×3/8＋600×4/8＝1125 元。"],
  "115-mb-21": ["直線垂直於平面，就垂直於過垂足的平面內直線","AE 是長方體的直立邊，垂直底面 EFGH。EG 在底面且經過 E，所以 AE 與 EG 垂直。","AB 和 AC 在同一面，分別是邊與對角線。AB 和 DH 不相交，為歪斜線。"],
  "115-mb-22": ["空間點到軸、到平面的距離","P 到 y 軸最近的點是 (0,−2,0)。差的兩個分量是 x＝3、z＝4，所以 a＝√(3²＋4²)＝5。","yz 平面上的點 x 都等於 0，b＝|3|＝3。總和是 8。"],
  "115-mb-23": ["聯立不等式找三角形面積","整理為 1−x≤y≤x＋1 與 x≤3。兩條斜線交於 (0,1)。","在 x＝3 時，上下交點為 (3,4)、(3,−2)。底長 6，頂點離直線 x＝3 有 3 單位，面積＝6×3÷2＝9。"],
  "115-mb-24": ["矩陣相乘可只算需要的那一欄","左矩陣乘右矩陣的第一欄 (p,r)，結果要是 (1,0)，所以 6p＋5r＝1、4p＋3r＝0。","由第二式得 r＝−4p/3，代入第一式得 −2p/3＝1，故 p＝−3/2。"],
  "115-mb-25": ["餘弦定理和三角形內角和","A 的對邊為 6、鄰邊是 3 和 4，cos A＝(3²＋4²−6²)/(2×3×4)＝−11/24。","B＋C＝180°−A，餘弦正負相反，所以 cos(B＋C)＝11/24。"],
  "115-mb-26": ["兩邊夾角求三角形面積","極坐標第一個數是距離，所以 OA＝4、OB＝3；方向差為 268°−118°＝150°。","面積＝(1/2)×4×3×sin 150°＝6×1/2＝3。"],
  "115-mb-27": ["正弦週期由 x 的係數決定","sin 的角度增加 2π 才繞完一圈。題目把 x 乘以 3，所以 x 只需加 2π/3。","外面的 2 改變高度，＋1 改變上下位置，角度內的 −π/3 改變起點，週期維持 2π/3。"],
  "115-mb-28": ["用垂直斜率與通過的點寫直線","12x＋5y＝0 的斜率是 −12/5，垂直的斜率是 5/12。代 x＝1 到 2x−y＝3 得 y＝−1。","過 (1,−1) 用點斜式 y＋1＝(5/12)(x−1)，整理得到 5x−12y＝17。"],
  "115-mb-29": ["放回抽取時，兩次機率相同","異色有先紅後藍與先藍後紅。紅球機率 2/5，藍球機率 3/5。","兩條路徑互斥，機率相加：(2/5)(3/5)＋(3/5)(2/5)＝12/25＝0.48。"],
  "115-mb-30": ["條件機率先縮小分母","點數和小於 7，依和 2、3、4、5、6 分別有 1、2、3、4、5 種有序結果，共 15 種。","至少一個 3 的是 (3,1)、(1,3)、(3,2)、(2,3)、(3,3)，所以是 5/15＝1/3。"],
  "115-mb-31": ["知道恰一人命中，分母只保留兩種情形","只有甲中是 0.6×0.5＝0.3，只有乙中是 0.4×0.5＝0.2。","已知恰一發命中，條件機率是 0.3/(0.3＋0.2)＝0.6。"],
  "115-mb-32": ["先固定總鳴叫次數，再排列長短","有 n 次鳴叫且 k 次是長音，總長是 n＋k＋(n−1) 秒，所以 k＝16−2n。","0≤k≤n 只允許 (n,k)=(6,4)、(7,2)、(8,0)。選長音位置共有 15＋21＋1＝37 種。"],
  "115-mb-33": ["餘式次數低於除式，且在 x＝1 等於 f(1)","除式 (x−1)² 是二次，所以餘式頂多一次。對稱中心 (1,3) 表示 f(1)＝3。","依序代入 x＝1，A、B、C、D 得 2、4、1、3。只有 3x 合條件。"],
  "115-mb-34": ["拋物線的等高兩點以對稱軸為中線","−3 和 5 對應相同函數值，所以對稱軸在 x＝(−3＋5)/2＝1。頂點在 y＝2x＋3 上，故為 (1,5)。","設 f(x)＝a(x−1)²＋5。代 x＝5 得 16a＋5＝−11，a＝−1。代 x＝0 得 4。"],
  "115-mb-35": ["比較向量長度可比較長度的平方","依序算得 A=(15,30)、B=(−24,12)、C=(30,10)、D=(−3,14)。","平方長度依序為 1125、720、1000、205；最大的是選項 A。"],
  "115-mb-36": ["垂直向量的長度可用畢氏定理","2u 和 v 也垂直。合成向量 (20,15) 的長度是 25，2u 的長度是 24。","|v|²＝25²−24²＝49，所以 |v|＝7。"],
  "115-mb-37": ["矩陣乘法要保留 AB 和 BA","(A＋B)²＝A²＋AB＋BA＋B²。題目給中間兩項等於 2AB，故 AB＝BA。","比較右上格：a−8＝−4−a，得 a＝2。比較左下格：6−b＝b＋12，得 b＝−3。和是 −1。"],
  "115-mb-38": ["等差對數對應原數的等比","設原數的公比為 r。從 162 到 1250 共乘四次，所以 r⁴＝1250/162＝625/81。","625＝5⁴、81＝3⁴，公比 r＝5/3。a＝162×5/3＝270。"],
  "115-mb-39": ["垂徑定理：圓心到弦的垂線通過弦中點","A 到對稱線 x＋y−10＝0 的距離是 |2＋4−10|/√2＝2√2，也就是半條弦長。","用半弦、圓心到弦的距離 4、半徑形成直角三角形，r＝√((2√2)²＋4²)＝2√6。"],
  "115-mb-40": ["分兩種同色結果，分別算剩下白球比例","甲乙皆白的機率是 (4/7)(3/6)＝12/42，皆黑是 (3/7)(2/6)＝6/42。已知同色後，權重分別是 2/3、1/3。","若皆白，餘 2 白 3 黑；若皆黑，餘 4 白 1 黑。剩餘五顆的抽取位置等可能，因此丁抽白為 (2/3)(2/5)＋(1/3)(4/5)＝8/15。"],
  "115-ch-1": ["字音比較","把兩字分開念。『絹』和『狷』都讀 ㄐㄩㄢˋ。","『鄲／憚』是 ㄉㄢ／ㄉㄢˋ，聲調不同。『楫／緝』是 ㄐㄧˊ／ㄑㄧˋ，『槊／溯』是 ㄕㄨㄛˋ／ㄙㄨˋ。"],
  "115-ch-2": ["同音字辨形","依意思把字寫回去。『阿諛』是奉承，『膏腴』指土地肥沃，『須臾』指很短的時間。","諛、腴、臾各不相同。B 後兩個用『闌』，C 有『靡』重複，D 前兩個都寫『梭』。"],
  "115-ch-3": ["一詞多義","先將『早晚』換成『遲早、終究』。成為天子、招致惡果，兩句都表示未來終將發生。","『大方之家』的大方指有學識的人。古詩中的『可憐』可指可愛，『故意』在詩中指老朋友的情意。"],
  "115-ch-4": ["常見錯別字","D 的『纏鬥、強勁、蟬聯』都符合意思。『蟬聯』指連續取得同一名次或頭銜。","A 應寫『一籌莫展』，B 應寫『匪夷所思』，C 應寫『詞不達意』。"],
  "115-ch-5": ["成語看情境","『虎尾春冰』把踩虎尾、踏薄冰並舉，形容處境危險。和後面的『稍一不慎』相扣。","『南轅北轍』表示方向相反，與默契十足不合。『玩歲愒日』指虛度光陰，和及時努力相反。"],
  "115-ch-6": ["詩句中的因果","『寺遠僧來少』可拆成因寺院離得遠，所以來的僧人少；『橋危客過稀』可拆成因橋危險，所以過橋的旅客少。","B 的兩個分句各自都有原因和結果，跟題幹的『草枯／鷹眼疾、雪盡／馬蹄輕』相同。"],
  "115-ch-7": ["律詩排序","先找開頭的時間線。『去年花裏逢君別』接『今日花開又一年』，起筆對照去年和今年。","接著由離別轉到世事與春愁，下一聯並列多病想歸田和百姓流亡之愧。末聯回到朋友將來探望，再以望月寫等待。"],
  "115-ch-8": ["教育類題辭","『桃李』比喻學生，『洙泗』聯想到孔子講學，『杏壇』指教育界，所以甲、丙、己都合用。","『杏林』指醫界，容易跟『杏壇』混淆。『千古』常作哀輓用語，用於退休祝賀不妥。"],
  "115-ch-9": ["文房四寶","找每聯的動作。甲『揮毫』用筆，丙『磨來濃霧』寫磨墨，乙『化石、窺池』指硯石和硯池。","丁『價重洛陽』連到洛陽紙貴。依筆、墨、紙、硯排列為甲丙丁乙。"],
  "115-ch-10": ["反詰與真問","反詰可以改寫成一句肯定或否定的陳述。例如『何患乎無兄弟』等於『不用擔心沒有兄弟』。","A 的『何日去』表達不知道何時能歸鄉，保留時間上的疑問。C 等於『真愉快』，D 等於『晉國沒有滿足的一天』。"],
  "115-ch-11": ["詩歌情境","『髭』是嘴邊的鬍鬚，『撚』是用手指搓捻。詩人寫自己思索詩句時常撚鬍鬚。","末句開玩笑說若一直撚斷，嘴邊就跟老和尚的頭一樣光。重點是寫詩苦思與習慣。"],
  "115-ch-12": ["詠史典故","『丹心、義氣』配合關羽忠義的形象，『春秋』也常用來連結關羽讀《春秋》的典故。","曹操頭疾和關羽手臂的典故指華佗。荔枝配楊貴妃。『明妃』指王昭君。"],
  "115-ch-13": ["功虧一簣","『簣』是一筐土。堆山到只差一筐時停下來，仍然沒有完成。","C 說挖井到很深還沒見水，放棄就仍是廢井。兩句都說做到最後一步才有效。"],
  "115-ch-14": ["抽象道理與例子","先讀主張『人人有不忍人之心』，再找具體情境。看到小孩快掉進井裡，會立刻驚懼同情。","這個例子用來說明人人有惻隱之心。A、B、C 的前後句主要順著事情或觀察經過發展。"],
  "115-ch-15": ["固定疊詞","完整詞形是小心翼翼、神采奕奕、鼎鼎大名、虎視眈眈、結實纍纍。","『奕奕』寫有精神，和下棋的『弈』不同。『纍纍』有連串多數的意思，用來描寫果實。"],
  "115-ch-16": ["比喻親恩","『昊天罔極』說浩大如天空、沒有邊際。『三春暉』以整個春天的陽光比喻母愛。","孩子如受陽光滋養的一寸小草，怎能回報全部恩情？兩句焦點都是父母恩澤之深。"],
  "115-ch-17": ["流水喻時間","『流波不相待』說流水不等人；『繁華及時紅』指出盛開有自己的時節。","兩句合讀有珍惜時光之意。B、C 的流水各自是景物的一部分，沒有這樣的勸勉。"],
  "115-ch-18": ["從景物辨季節","乙的楊柳新綠是春，甲的梅子與芭蕉是初夏，丙的霜楓是秋。","丁的荷葉枯盡、菊花殘而仍抗霜，寫秋末初冬。依序乙甲丙丁。"],
  "115-ch-19": ["中心風尚向外擴散","城裡喜歡高髻，外地梳得更高；城裡喜歡寬眉，外地幾乎畫半個額頭。","『風行草偃』是上行下效，『變本加厲』是模仿者程度更甚，恰好說出兩層。"],
  "115-ch-20": ["由物象判斷詠物","『堅硬的環節』提示竹節，『向天空步步高升』寫竹幹逐節向上長，『綠』是竹的色彩。","B 的攀附動作更接近藤蔓。C 的去舊迎新指節慶爆竹，題意重視可辨認的物象。"],
  "115-ch-21": ["先秦思想關鍵詞","性惡而以禮義改變，是荀子。桂木與漆樹因有用受損，反思無用之用，是莊子。","『兼相愛則治』講兼愛，是墨子的主張。因此是荀子、莊子、墨子。"],
  "115-ch-22": ["唐詩與宋詩風格","先依題幹找日常場景和口語敘事。C 寫高個子讀書，伸懶腰就撞到屋頂，帶有生活趣味。","A 用日暮、江月寫旅愁，B 借月落鳥啼等寫夢醒後的思緒，D 借寒雨送別寄情。"],
  "115-ch-23": ["偏義複詞","把左右兩字拆開看。『不宜異同』說賞罰標準不宜有分別，實際取『異』義。","『圓缺』真涵蓋月亮圓和缺，『冷暖』也涵蓋冷和暖，兩字都有用。"],
  "115-ch-24": ["層遞修辭","先找表示階段的時間詞：開始解牛、三年後、現在。","庖丁起初見整頭牛，三年後能看出結構，最後憑神會而毋須用眼。三步逐層提升；C 的三個做法則平行列舉。"],
  "115-ch-25": ["節慶意象","『登高、插茱萸』是農曆九月九日重陽節的線索。B 將它配為端午，符合題目要找的錯配。","除歲換桃符是春節，牛郎織女相會是七夕乞巧，夜間燈火與魚龍舞是元宵。"],
  "115-ch-26": ["古典小說特色","《老殘遊記》以老殘的所見所聞串連，沿途描寫官場與民間處境，帶出作者對國事與民生的看法。","《儒林外史》重在諷刺科舉與士林。《世說新語》所記以漢末至東晉士人為主，時代早於唐。"],
  "115-ch-27": ["閱讀定位與反向題","先注意問『並非』。第一段寫冰期縮短，意思是結冰的時間變少。","D 說湖泊水面永久凍結，方向相反。垂直遷徙、族群縮減、食物鏈重整都能在原文定位。"],
  "115-ch-28": ["文本敘述與推論","首段說颱風連連、規模愈大。選項 A 的『風災消失』與這條線索直接矛盾。","同一選項即使有對的部分，只要有一個關鍵錯誤，整項就不成立。"],
  "115-ch-29": ["人物前後變化","仲永五歲就能作詩，後來十二三歲已不如從前，七年後和一般人一樣。","『小時了了，大未必佳』就是小時候聰明，長大未必突出，符合故事的發展。"],
  "115-ch-30": ["由末段議論找主旨","『受之天』指天資，『受於人』指後天教育。末段說仲永很有天分，卻缺少後天學習而落入平常。","父親重利是故事原因之一，作者由此談的是後天教育對才能的影響。"],
  "115-en-1": ["grow＝生長","句意是強勁海風吹來，有些植物很難在這片海灘生長。主語 some plants 提示 grow。","blow 是風在吹，cure 是治療，cage 是把東西關進籠子。"],
  "115-en-2": ["confirm a reservation＝確認訂位","Lisa 打給航空公司，目的在確認 flight reservation（航班訂位）。","arrest 是逮捕，resist 是抵抗，commute 是通勤。遇到航空公司和訂位，記 confirm / change / cancel 三種常見搭配。"],
  "115-en-3": ["fierce＝猛烈的","後面說房屋被毀、居民必須撤離，空格要描述暴風雨的強度。fierce storm 是猛烈的暴風雨。","childish 幼稚的，classical 古典的，financial 財務的。"],
  "115-en-4": ["structure＝建築物、構造","前面說 Taipei 101 是高樓，後半句仍把它放在許多壯觀的建物中比較。","one of the most + 形容詞 + 複數名詞，表示『最……的其中之一』。structures 指這些建物。"],
  "115-en-5": ["abnormal＝不正常的","never happened in the past、extreme heat、excessive rain 都是異常天候的線索。","standard 是標準的，意思相反。flexible 是有彈性的，cognitive 是認知的。"],
  "115-en-6": ["worship＝敬拜","churches、temples、mosques 都是宗教活動場所，prayer 是祈禱。","gather to worship 是聚集來禮拜。preserve 保存，prohibit 禁止，exclude 排除。"],
  "115-en-7": ["travel agency＝旅行社","後文說提供機票和飯店套裝優惠，指辦理旅行的機構。","tutor 是家教，rumor 是謠言，legacy 是留下的遺產或影響。"],
  "115-en-8": ["concentration＝濃度","high concentration of sugar 指飲料內含糖濃度高，接著說每天喝不健康。","circulation 循環，congratulation 祝賀，calculation 計算。"],
  "115-en-9": ["strive for＝努力追求","下一句 work hard to pursue excellence 等於替前一句解釋。strive for perfection 是盡力追求完美。","ensure 是確保，通常直接接名詞。protest 是抗議，inspire 是激勵。"],
  "115-en-10": ["be respectful of＝尊重","inclusive environment 指包容的環境。面對彼此意見與文化背景，合理態度是尊重。","dominant 支配的，accurate 精確的，furious 暴怒的。"],
  "115-en-11": ["in spite of＝儘管","天氣糟糕，本來可能放棄，登山隊卻繼續往上。前後呈讓步。","in spite of 後面接名詞 the terrible weather。because of 是『因為』，would make 壞天氣成為繼續登山的原因，語意不合。"],
  "115-en-12": ["break the ice＝打破僵局","兩人起初幾乎不講話，合作之後關係變得自在。break the ice 就是消除初見的尷尬。","全句寫過去經過，所以用過去式 broke。make waves 指引起轟動，spring up 指突然出現。"],
  "115-en-13": ["draw on＝利用、借助","建置健康照護體系，需要運用不同醫院的 medical resources。draw on 後接資源、經驗或知識。","take up 可指開始從事或占用，put off 是延後，knock down 是推倒。"],
  "115-en-14": ["come to an agreement＝達成協議","談判好幾週後，雙方終於達成協議。an agreement 是固定搭配的線索。","turn down 是拒絕，give up 是放棄，tune out 是不再留意。"],
  "115-en-15": ["in place of＝取代","使用再生能源的目的是降低碳足跡，因此把傳統化石燃料替換掉。","on behalf of 代表，in charge of 負責，in light of 鑑於。"],
  "115-en-16": ["strike a balance between A and B＝在兩者間取得平衡","A 是建設基礎設施，B 是保護綠地。都市規劃需要兼顧。","keep in shape 是維持體態，get cold feet 是臨陣退縮，come to a standstill 是停擺。"],
  "115-en-17": ["get over＝克服","受訓之後，Mark 克服了害怕深池游泳的心理。get over a fear 是常見搭配。","get off 常指下車，call off 是取消，call out 可指點名或公開批評。"],
  "115-en-18": ["on top of that＝除此之外","第一句談身體和免疫，第二句再加入心理健康與減壓兩個好處。","On the contrary 表相反，Worst of all 加重壞處，That is to say 是換句話重述。"],
  "115-en-19": ["than 提示比較級","difficult 字較長，比較級是 more difficult。much 放在比較級前，把差距加強成『難得多』。","difficulty 是名詞，most difficult 是最高級。只寫 difficult 無法和 than 組成這個比較句型。"],
  "115-en-20": ["little 修飾不可數名詞","time 表示剩下的時間，這裡不可數。must finish quickly 說得趕快做完，所以剩的時間很少。","few、many 搭可數複數。much 可搭 time，卻是『很多』的意思。"],
  "115-en-21": ["過去分詞開頭表被動","誰把 Sandra 養大？是別人把她養大，所以她是被養育的一方。用 Raised in a small village。","可以展開理解為 Having been raised in a small village 或 Because she was raised there。"],
  "115-en-22": ["deny + V-ing＝否認做過某事","先看到 denied，後面講他否認在賽事中用藥。記 deny doing something。","直接接 taking；deny 和 decide to do 的接法不同。"],
  "115-en-23": ["whose 表示所有關係","innovative ideas 是那位商界人士的點子。用 whose innovative ideas 把名詞和所有者連起來。","who 和 whom 可以表示人，單獨放在 ideas 前面不能表達『其點子』。"],
  "115-en-24": ["混合假設句","when I was young 指過去，now 指現在。這句是假設過去若更努力，現在會有更好的工作機會。","過去和事實相反用 If + 主詞 + had + 過去分詞，現在的結果用 would + 原形動詞。"],
  "115-en-25": ["助動詞代替前文動詞","those 指其他孩子。前半句 who read regularly 是一般現在式，後半句 who don’t 省略 read regularly。","aren’t 和 weren’t 是 be 動詞，無法代替 read。haven’t 則需要前文是完成式或有相應語境。"],
  "115-en-26": ["since 在這裡＝因為","餐廳收到極正面的評論，因此很快受歡迎。前半句提供原因。","unless 除非，as though 彷彿，even though 儘管。這三項都不合此處的因果。"],
  "115-en-27": ["被動語態 be + 過去分詞","家事由家人分擔。housework 是不可數名詞，用單數 is，搭配過去分詞 shared。","were 和單數主語不搭；has been sharing、will share 會變成家事主動去分攤。"],
  "115-en-28": ["rather than＝而非、與其……不如……","主管會怪團隊成員而不肯道歉。對照 blame 和 offer，兩者都用原形。","instead 如果要接動作用 instead of offering；B 的 offered 也不能直接和 would blame 平行。"],
  "115-en-29": ["要求句型 insist that + 主詞 + 原形","句中 insists 表示『堅持要求』員工準時。that 後用原形 be。","這個用法和 insist 表示『堅稱某事是真的』不同。這題談要求，句型可理解為 should be。"],
  "115-en-30": ["逗號加 which 指前面整件事","班長投票反對提案，這一整件事讓所有人吃驚。用 which 接補充結果。","逗號後的補充關係子句用 which，不能用 that。and surprising 則缺少完整平行結構。"],
  "115-en-31": ["Not until 句首倒裝","直到簡報結束，講者才發現自己漏講重點。Not until 提到句首時，主要子句變成 did the speaker realize。","until 後的 the presentation ended 仍用正常語序。這題看到 did 在主詞前，就可辨認倒裝。"],
  "115-en-32": ["It is said that＝據說","It 是形式主詞，真正被人傳述的內容在 that 後面。句意是據說建築已存在五百多年。","There is 常用來表示某物存在，不能直接接 said that 作這個句型。"],
  "115-en-33": ["間接問句使用主詞＋動詞","the tourists asked the guide 後接間接問句。B 的 they should visit 使用正常語序，A 和 D 保留直接問句的倒裝。","原卷採 B。自己寫作時可用更自然的 where they should go，或 which places they should visit。"],
  "115-en-34": ["whoever＝任何……的人","空格所在的整段要充當 will receive 的主詞。Whoever discovers the cure 等於 Anyone who discovers the cure。","Anyone discovers 缺 who，No matter who 開頭通常帶讓步副詞子句，無法充當此處主詞。"],
  "115-en-35": ["文章主旨看開頭和結尾","首段說 Hamberg 對國家公園的創立與推廣很重要，末段說他的研究改變外界對 Sarek 的看法。","D 涵蓋首尾。冰河、國家公園制度及與其他科學家合作都是支撐主旨的細節。"],
  "115-en-36": ["篇章組織看年代","文章先寫 1895 年初到 Sarek，再寫持續研究、1909 年設公園，最後到 1996 年的世界遺產。","這種由早到晚呈現事件的組織叫 in order of time（時間順序）。"],
  "115-en-37": ["細節題回到第二段","第二段寫多數瑞典人認為山區危險可怕，Hamberg 卻看到很大的科學價值。C 說此前少有人知道其科學價值。","A 的 alone 和文中 joined forces 不合。B 說因礦藏而開發，文章沒有這條因果。"],
  "115-en-38": ["推論題抓先後關係","第二段開頭寫他 1895 年到 Sarek 之前，曾加入探索格陵蘭冰河的團隊。","因此可推知 B。文章說木屋是為觀測而建，並無普遍木屋、放逐族人或以觀光為研究目的的資訊。"],
  "115-en-39": ["intimidating＝令人畏懼的","第二段用 dangerous and frightening 描述當時大眾對山區的印象，末段在重提這個印象。","terrifying 也是令人害怕的。promising 有希望的，appealing 吸引人的，outgoing 外向的。"],
  "115-en-40": ["結尾段作用","最後一段把過去看成可怕荒野，與後來被認為美麗且獲列世界遺產的轉變連起來。","重點是總結 Hamberg 的貢獻，所以選 offering conclusive remarks（提出總結）。"]
};
